<template>
  <div :class="['detail-page', isSalesView ? 'detail-page--sales' : 'detail-page--procurement']" v-loading="loading">
    <div class="back-row">
      <el-button link class="back" @click="router.push(listPath)">← {{ t(isSalesView ? 'sourcingDetail.backSales' : 'sourcingDetail.backProcurement') }}</el-button>
    </div>
    <template v-if="detail">
      <header class="hero">
        <div><span class="detail-perspective">{{ t(isSalesView ? 'sourcingDetail.salesPerspective' : 'sourcingDetail.procurementPerspective') }}</span><small>{{ t(isSalesView ? 'sourcingDetail.customerInquiry' : 'sourcingDetail.sourcingTask') }} · {{ detail.caseNo }}</small><h1>{{ detail.title || t('sourcingDetail.untitled') }}</h1><p>{{ t('sourcingDetail.customer') }} {{ detail.customerName || t('sourcingDetail.unlinked') }} · {{ t('sourcingDetail.contact') }} {{ detail.contactName || detail.contactEmail || '—' }} · {{ t('sourcingDetail.owner') }} {{ detail.ownerName || '—' }} · {{ t('sourcingDetail.source') }} {{ t(hasId(detail.sourceMailId) ? 'sourcingDetail.mailSource' : 'sourcingDetail.manualSource') }}</p></div>
        <div class="hero-actions"><el-button v-if="canOpenPeer" @click="openPeerView">{{ t(isSalesView ? 'sourcingDetail.viewProcurement' : 'sourcingDetail.viewSales') }}</el-button><el-button v-if="hasId(detail.sourceMailId)" @click="openSourceMail">{{ t('sourcingDetail.viewSourceMail') }}</el-button><el-button v-if="detail.sourceFileUrl" @click="openSourceFile">{{ t('sourcingDetail.downloadOriginal') }}</el-button><el-tag size="large" effect="dark">{{ displayStatusLabel }}</el-tag></div>
      </header>
      <section class="progress-card">
        <div v-for="(item,index) in progressStages" :key="item.key" :class="['stage',{active:index<=detailStageIndex}]"><b>{{ index+1 }}</b><span>{{ item.label }}</span></div>
        <aside><small>{{ t('sourcingDetail.currentTodo') }}</small><strong>{{ currentWaitingText }}</strong></aside>
      </section>

      <section class="handoff-card">
        <div><small>{{ t('sourcingDetail.handoff') }}</small><strong>{{ t('sourcingDetail.requirement') }} V{{ detail.requirementVersionNo || 1 }} · {{ handoffLabel }}</strong><p v-if="detail.returnReason">{{ t('sourcingDetail.returnReason') }}: {{ detail.returnReason }}<span v-if="detail.returnFields?.length">（{{ t('sourcingDetail.needsSupplement',{fields:detail.returnFields.join(', ')}) }}）</span></p><p v-else>{{ handoffHint }}</p></div>
        <div v-if="!isSalesView&&detail.handoffStatus==='WAITING_ACCEPTANCE'&&canWrite" class="handoff-actions"><el-button @click="returnOpen=true">退回补充</el-button></div>
      </section>

      <section v-if="!isSalesView" class="participant-card">
        <div class="participant-head"><div><small>采购协作</small><strong>主责：{{ primaryParticipant?.employeeName || '暂未指定' }} · {{ participants.length }} 人参与</strong><p>主责协调进度和统一提交，不会锁定案件；其他采购仍可并行询价和上报。</p></div><div class="handoff-actions"><el-button v-if="canWrite&&!currentParticipant" @click="joinCase">参与询价</el-button><el-button v-if="canWrite&&currentParticipant?.role!=='PRIMARY'&&!currentParticipant?.primaryRequestedAt" type="primary" plain @click="requestPrimary">{{ primaryParticipant?'申请成为主责':'成为主责采购' }}</el-button><el-tag v-if="currentParticipant?.primaryRequestedAt" type="warning">主责申请待处理</el-tag></div></div>
        <div v-if="participants.length" class="participant-list"><div v-for="item in participants" :key="item.id" class="participant-item"><span><b>{{ item.employeeName }}</b><small>加入于 {{ formatTime(item.joinedAt) }}</small></span><div><el-tag v-if="item.role==='PRIMARY'" type="success">主责采购</el-tag><el-tag v-else-if="item.primaryRequestedAt" type="warning">申请主责</el-tag><el-tag v-else>协作采购</el-tag><el-button v-if="canApprove&&item.role!=='PRIMARY'" link type="primary" @click="assignPrimary(item)">设为主责</el-button></div></div></div>
        <el-empty v-else description="暂无采购参与；任何采购专员都可以先加入，未设置主责不会锁定案件" :image-size="54" />
      </section>

      <section class="content-card">
        <el-tabs v-model="tab" @tab-change="loadTab">
          <el-tab-pane :label="t(isSalesView ? 'sourcingDetail.tabs.products' : 'sourcingDetail.needsSnapshot')" name="products">
            <div class="section-head"><div><h2>{{ t(isSalesView ? 'sourcingDetail.needsTitle' : 'sourcingDetail.needsSnapshot') }}</h2><p>{{ t(isSalesView ? 'sourcingDetail.needsSalesHint' : 'sourcingDetail.needsProcurementHint') }}</p></div><el-tag type="success" effect="plain">{{ t('sourcingDetail.requirement') }} V{{ detail.requirementVersionNo || 1 }}</el-tag></div>
            <el-table :data="productDemandGroups" row-key="key" :row-class-name="demandGroupRowClass">
              <el-table-column type="expand" width="44">
                <template #default="{row}">
                  <div class="demand-detail">
                    <div class="demand-detail__head"><strong>{{ t('sourcingDetail.specDetails') }}</strong><span>{{ t('sourcingDetail.groupedLines',{count:row.lines.length}) }}</span></div>
                    <el-table :data="row.lines" row-key="id" size="small" border>
                      <el-table-column prop="lineNo" label="#" width="55" />
                      <el-table-column :label="t('sourcingDetail.templateSpec')" min-width="440"><template #default="{row:line}"><span class="spec-summary">{{ specificationSummary(line.extracted) }}</span></template></el-table-column>
                      <el-table-column :label="t('sourcingDetail.quantity')" width="150"><template #default="{row:line}">{{ line.extracted.quantity||'—' }} {{ line.extracted.quantityUnit }}</template></el-table-column>
                      <el-table-column :label="t('sourcingDetail.sourceLabel')" width="140"><template #default><el-tag type="success" effect="plain">{{ t('sourcingDetail.reviewed') }}</el-tag></template></el-table-column>
                    </el-table>
                  </div>
                </template>
              </el-table-column>
              <el-table-column :label="t('sourcingDetail.lineLabel')" width="72"><template #default="{row}">{{ demandLineNumbers(row) }}</template></el-table-column>
              <el-table-column :label="t('sourcingDetail.productAndStandard')" min-width="260"><template #default="{row}"><strong>{{ localizedProductName(row.lines[0]) }}</strong><small>{{ demandStandards(row) }}</small></template></el-table-column>
              <el-table-column :label="t('sourcingDetail.templateSpec')" min-width="300"><template #default="{row}"><template v-if="row.lines.length>1"><strong>{{ t('sourcingDetail.groupedSpecs',{count:row.lines.length}) }}</strong><small>{{ t('sourcingDetail.clickForDetails') }}</small></template><span v-else class="spec-summary">{{ specificationSummary(row.lines[0].extracted) }}</span></template></el-table-column>
              <el-table-column :label="t('sourcingDetail.quantity')" width="165"><template #default="{row}"><strong>{{ demandQuantitySummary(row.lines) }}</strong><small v-if="row.lines.length>1">{{ t('sourcingDetail.groupTotal') }}</small></template></el-table-column>
              <el-table-column :label="t('sourcingDetail.sourceLabel')" width="130"><template #default><el-tag type="success" effect="plain">{{ t('sourcingDetail.reviewed') }}</el-tag></template></el-table-column>
            </el-table>
          </el-tab-pane>

          <el-tab-pane v-if="isSalesView" :label="t('sourcingDetail.tabs.procurementProgress')" name="procurementProgress">
            <div class="section-head"><div><h2>{{ t('sourcingDetail.progressTitle') }}</h2><p>{{ t('sourcingDetail.progressHint') }}</p></div><el-button link type="primary" @click="openPeerView">{{ t('sourcingDetail.openProcurement') }}</el-button></div>
            <div class="perspective-summary"><div><small>{{ t('sourcingDetail.currentStage') }}</small><strong>{{ displayStatusLabel }}</strong></div><div><small>{{ t('sourcingDetail.startedRfqs') }}</small><strong>{{ rfqs.length }}</strong></div><div><small>{{ t('sourcingDetail.receivedQuotes') }}</small><strong>{{ quotedRfqCount }}</strong></div><div><small>{{ t('sourcingDetail.confirmedBasis') }}</small><strong>{{ confirmedCosts.length }}</strong></div></div>
          </el-tab-pane>

          <el-tab-pane v-if="isSalesView" :label="t('sourcingDetail.tabs.quotationBasis')" name="quotationBasis">
            <div class="section-head"><div><h2>{{ t('sourcingDetail.basisTitle') }}</h2><p>{{ t('sourcingDetail.basisHint') }}</p></div></div>
            <el-alert v-if="procurementPlans.length&&!confirmedCosts.length" type="info" :closable="false" show-icon style="margin-bottom:12px" :title="t('sourcingDetail.basisWaiting')" />
            <el-table :data="confirmedCosts"><el-table-column :label="t('sourcingDetail.versionPathLabel')" width="230"><template #default="{row}"><strong>{{ t('sourcingDetail.versionPath',{requirement:row.requirementVersionNo||1,cost:row.versionNo||1}) }}</strong><small>{{ row.scenarioNo }}</small></template></el-table-column><el-table-column prop="currency" :label="t('sourcingDetail.currency')" width="100"/><el-table-column prop="customerTotal" :label="t('sourcingDetail.suggestedAmount')"/><el-table-column :label="t('sourcingDetail.customerQuote')" width="150"><template #default="{row}"><el-tag :type="customerQuotationPresentation(row).type">{{ customerQuotationPresentation(row).label }}</el-tag></template></el-table-column><el-table-column v-if="canCreateQuotation" :label="t('sourcingDetail.action')" width="130"><template #default="{row}"><el-button v-if="row.status==='CONFIRMED'&&row.submittedToSalesAt" link type="primary" @click="createCustomerQuotation(row)">{{ t(Number(row.customerQuotationId||0)>0?'sourcingDetail.openQuote':'sourcingDetail.generateQuote') }}</el-button></template></el-table-column></el-table>
            <el-empty v-if="!confirmedCosts.length" :description="t('sourcingDetail.noBasis')" />
          </el-tab-pane>

          <el-tab-pane v-if="!isSalesView" label="工厂询价" name="rfqs">
            <div class="section-head"><div><h2>工厂询价</h2><p>采购专员自行联系供应商或工厂；系统不记录沟通过程，只登记询价对象并录入最终报价。</p></div><el-button v-if="canWrite&&currentParticipant" type="primary" :disabled="!rfqEligibleLines.length" @click="openRFQ">{{ rfqs.length ? '新增工厂询价' : '创建首个工厂询价' }}</el-button></div>
            <el-empty v-if="!rfqs.length" :description="currentParticipant?'尚未创建工厂询价':'请先在上方参与本案件'"><el-button v-if="canWrite&&currentParticipant" type="primary" @click="openRFQ">创建首个工厂询价</el-button></el-empty>
            <el-table :data="rfqs">
              <el-table-column prop="rfqNo" label="询价编号" width="185" />
              <el-table-column label="供应商 / 生产工厂" min-width="230"><template #default="{row}"><strong>{{ row.supplierName }}</strong><small>{{ row.factoryName||'未指定生产工厂' }} · 报价人 {{ row.createdByName||'—' }}</small></template></el-table-column>
              <el-table-column label="询价产品" min-width="210"><template #default="{row}"><strong>{{ rfqProductSummary(row) }}</strong><small>人工沟通不在系统中记录</small></template></el-table-column>
              <el-table-column label="状态" width="130"><template #default="{row}"><el-tag :type="rfqType(row)">{{ rfqLabel(row) }}</el-tag></template></el-table-column>
              <el-table-column label="操作" width="76" align="center" fixed="right"><template #default="{row}"><el-dropdown trigger="click" @command="handleRFQAction($event,row)"><el-button text circle aria-label="操作"><span aria-hidden="true">•••</span></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="download">下载询价单</el-dropdown-item><el-dropdown-item v-if="canPrice&&auth.owns(String(row.createdBy))" command="quote" divided>录入新报价</el-dropdown-item><el-dropdown-item v-if="canPrice&&auth.owns(String(row.createdBy))" command="import">导入报价</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template></el-table-column>
            </el-table>
          </el-tab-pane>

          <el-tab-pane v-if="!isSalesView" label="产品报价组" name="quotes">
            <div class="section-head"><div><h2>产品组报价比较</h2><p>这里自动汇总“工厂询价”中已经录入的报价，只用于按产品比较，不在比较页重复录入。</p></div><div class="quote-sort"><span>排序方式</span><el-select v-model="comparisonSort" style="width:170px"><el-option value="PRICE" label="单价：从低到高"/><el-option value="LEAD_TIME" label="生产周期：从短到长"/><el-option value="MOQ" label="MOQ：从低到高"/></el-select></div></div>
            <div class="quote-summary"><div><b>{{ participants.length }}</b><span>参与采购</span></div><div><b>{{ latestQuoteLines.length }}</b><span>当前有效报价</span></div><div><b>{{ quoteLines.length-latestQuoteLines.length }}</b><span>历史版本</span></div></div>
            <el-empty v-if="!comparisonQuoteGroups.length" description="当前案件没有可报价的产品" />
            <div v-else class="quote-compare-groups">
              <section v-for="group in comparisonQuoteGroups" :key="group.sourcingLineId" class="quote-product-card">
                <header><div><small>产品行 #{{ sourceLineNo(group.sourcingLineId) }}</small><h3>{{ sourceProduct(group.sourcingLineId) }}</h3><p class="product-spec">模板规格：{{ sourceSpecification(group.sourcingLineId) }}</p><p>客户需求：{{ sourceQuantity(group.sourcingLineId) }} {{ sourceUom(group.sourcingLineId) }}</p></div><div class="quote-product-meta"><el-tag effect="plain">{{ activeQuoteRows(group.rows).length }} 份当前有效报价</el-tag><small>{{ comparisonSortLabel }}</small></div></header>
                <el-empty v-if="!activeQuoteRows(group.rows).length" description="当前报价已退回，等待采购专员提交新版本" :image-size="70" />
                <el-table v-else :data="activeQuoteRows(group.rows)">
                  <el-table-column label="供应商 / 报价人" min-width="210"><template #default="{row}"><strong>{{ row.supplierName }}</strong><small>{{ quoteFactoryName(row) }} · {{ row.createdByName||'—' }}</small></template></el-table-column>
                  <el-table-column label="最新单价" min-width="205"><template #default="{row}"><strong class="quote-price">{{ row.currency }} {{ row.unitPrice }}/{{ sourceUom(row.sourcingLineId) }}</strong><el-tag v-if="isLowest(row)" size="small" type="success">最低单价</el-tag><small v-if="row.comparePrice&&row.compareCurrency!==row.currency" class="quote-compare">≈ {{ row.compareCurrency }} {{ row.comparePrice }}</small></template></el-table-column>
                  <el-table-column label="可供量" width="145"><template #default="{row}">{{ row.qty || '—' }} {{ sourceUom(row.sourcingLineId) }}</template></el-table-column>
                  <el-table-column label="MOQ" width="135"><template #default="{row}">{{ row.moq || '—' }}<span v-if="row.moq"> {{ sourceUom(row.sourcingLineId) }}</span></template></el-table-column>
                  <el-table-column label="生产周期" width="115"><template #default="{row}">{{ row.leadTime || '—' }}<span v-if="row.leadTime"> 天</span></template></el-table-column>
                  <el-table-column prop="paymentTerms" label="付款条件" min-width="150"/>
                  <el-table-column prop="incoterm" label="贸易条款" width="110"/>
                  <el-table-column label="有效期" width="125"><template #default="{row}"><span>{{ row.validUntil||'—' }}</span><el-tag v-if="isQuoteExpired(row)" size="small" type="danger">已过期</el-tag></template></el-table-column>
                  <el-table-column label="版本" width="105"><template #default="{row}"><strong>V{{ row.versionNo||1 }}</strong><small>{{ row.supplierQuoteNo }}</small></template></el-table-column>
                  <el-table-column label="操作" width="140" fixed="right"><template #default="{row}"><el-button link @click="openQuoteHistory(row)">历史</el-button><el-button v-if="canApprove" link type="warning" @click="openQuoteRework(row)">退回</el-button></template></el-table-column>
                </el-table>
              </section>
            </div>
          </el-tab-pane>

          <el-tab-pane :label="t('sourcingDetail.tabs.shipping')" name="shipping">
            <div class="section-head"><div><h2>{{ t('sourcingDetail.shippingTitle') }}</h2><p>{{ t('sourcingDetail.shippingHint') }}</p></div><el-tag :type="shippingStatus(shippingCollaboration?.shippingRequest?.status).type">{{ shippingStatus(shippingCollaboration?.shippingRequest?.status).label }}</el-tag></div>
            <el-descriptions v-if="shippingCollaboration?.shippingRequest" :column="2" border class="shipping-summary">
              <el-descriptions-item :label="t('sourcingDetail.salesOwner')">{{ shippingCollaboration.shippingRequest.salesEmployeeName || '—' }}</el-descriptions-item>
              <el-descriptions-item :label="t('sourcingDetail.destinationPort')">{{ shippingCollaboration.shippingRequest.destinationPort || t('sourcingDetail.pending') }}</el-descriptions-item>
              <el-descriptions-item :label="t('sourcingDetail.cargo')" :span="2">{{ localizedCargoSummary() }}</el-descriptions-item>
            </el-descriptions>
            <el-empty v-if="!shippingCollaboration?.plans?.length" :description="t('sourcingDetail.noShippingPlan')" />
            <el-card v-for="plan in shippingCollaboration?.plans || []" :key="plan.id" shadow="never" class="manager-plan-card">
              <header><div><small>{{ t('sourcingDetail.planVersion',{requirement:plan.requirementVersionNo||1,plan:plan.versionNo||1}) }}</small><h3>{{ plan.planNo }}</h3><p>{{ t('sourcingDetail.managerNote') }}: {{ plan.managerNote || '—' }}</p></div><div><el-tag type="success">{{ t('sourcingDetail.submittedSales') }}</el-tag><small>{{ t('sourcingDetail.salesOwner') }}: {{ plan.targetSalesName || '—' }}</small></div></header>
              <el-table :data="plan.items"><el-table-column :label="t('sourcingDetail.cargo')" min-width="150"><template #default="{row}">{{ localizedLineProduct(row.sourcingLineId,row.productName) }}</template></el-table-column><el-table-column :label="t('sourcingDetail.recommendedLevel')" width="110"><template #default="{row}"><el-tag :type="row.selectionType==='RECOMMENDED'?'success':'info'">{{ t(row.selectionType==='RECOMMENDED'?'sourcingDetail.recommended':'sourcingDetail.alternative') }}</el-tag></template></el-table-column><el-table-column :label="t('sourcingDetail.carrier')" min-width="190"><template #default="{row}">{{ row.carrierForwarder }}<small>{{ row.serviceOptionName || t('sourcingDetail.defaultSchedule') }}</small></template></el-table-column><el-table-column :label="t('sourcingDetail.freight')" min-width="150"><template #default="{row}"><strong>{{ row.currency }} {{ row.totalFreight }}</strong><small>{{ shippingBasisLabel(row.chargeBasis) }} · {{ t('sourcingDetail.unitPrice') }} {{ row.unitRate }}</small></template></el-table-column><el-table-column :label="t('sourcingDetail.departureArrival')" min-width="190"><template #default="{row}">{{ row.estimatedDeparture || '—' }} → {{ row.estimatedArrival || '—' }}</template></el-table-column><el-table-column :label="t('sourcingDetail.managerDecision')" min-width="210"><template #default="{row}"><strong>{{ t('sourcingDetail.reason') }}: {{ row.reason || '—' }}</strong><small>{{ t('sourcingDetail.risk') }}: {{ row.risk || t('sourcingDetail.none') }}</small></template></el-table-column></el-table>
            </el-card>
          </el-tab-pane>

          <el-tab-pane :label="t('sourcingDetail.tabs.plans')" name="plans">
            <div class="section-head"><div><h2>{{ isSalesView?t('sourcingDetail.managerPlanTitle'):'经理统一采购方案' }}</h2><p>{{ isSalesView?t('sourcingDetail.managerPlanHint'):'从各产品组选择一个或多个报价，标记推荐和备选后整合成一份方案。经理不填写采购数量。' }}</p></div><div v-if="!isSalesView&&canApprove" class="handoff-actions"><el-button @click="openAddSupplierRework">要求新增供应商</el-button><el-button type="primary" :disabled="!confirmedComparisonQuoteLines.length" @click="openProcurementPlan">生成统一方案</el-button></div></div>
            <el-empty v-if="!procurementPlans.length" :description="isSalesView?t('sourcingDetail.noManagerPlan'):'尚未生成经理统一方案'" />
            <div v-else class="manager-plan-list">
              <section v-for="plan in procurementPlans" :key="plan.id" class="manager-plan-card">
                <header><div><small>{{ t('sourcingDetail.unifiedPlanVersion',{requirement:plan.requirementVersionNo||1,plan:plan.versionNo||1}) }}</small><h3>{{ plan.planNo }}</h3><p>{{ t('sourcingDetail.managerNote') }}: {{ plan.managerNote||'—' }}</p></div><div class="manager-plan-actions"><el-tag :type="plan.status==='SUBMITTED_TO_SALES'?'success':plan.status==='SUPERSEDED'?'info':'warning'">{{ planStatusLabel(plan.status) }}</el-tag><small>{{ t('sourcingDetail.salesOwnerLabel') }}: {{ plan.targetSalesName||'—' }}</small><el-button v-if="!isSalesView&&canApprove&&plan.status==='CONFIRMED'" type="primary" size="small" @click="submitProcurementPlan(plan)">提交负责销售</el-button></div></header>
                <el-table :data="plan.items||[]" border>
                  <el-table-column :label="t('sourcingDetail.product')" min-width="150"><template #default="{row}">{{ localizedLineProduct(row.sourcingLineId,row.productName) }}</template></el-table-column>
                  <el-table-column :label="t('sourcingDetail.recommendedLevel')" width="115"><template #default="{row}"><el-tag :type="row.selectionType==='RECOMMENDED'?'success':row.selectionType==='REJECTED'?'danger':'info'">{{ row.selectionType==='REJECTED'?t('sourcingDetail.rejected'):t(row.selectionType==='RECOMMENDED'?'sourcingDetail.recommended':'sourcingDetail.alternative') }} {{ row.priority }}</el-tag></template></el-table-column>
                  <el-table-column :label="t('sourcingDetail.supplierBuyer')" min-width="190"><template #default="{row}"><strong>{{ row.supplierName }}</strong><small>{{ row.factoryName||'—' }} · {{ row.buyerName }}</small></template></el-table-column>
                  <el-table-column :label="t('sourcingDetail.quotation')" min-width="155"><template #default="{row}"><strong>{{ row.currency }} {{ row.unitPrice }}/{{ row.uomCode }}</strong><small>{{ t('sourcingDetail.available') }} {{ row.availableQty }} {{ row.uomCode }} · V{{ row.quoteVersionNo }}</small></template></el-table-column>
                  <el-table-column prop="incoterm" :label="t('sourcingDetail.incoterm')" width="100"/>
                  <el-table-column prop="paymentTerms" :label="t('sourcingDetail.paymentTerms')" min-width="145"/>
                  <el-table-column :label="t('sourcingDetail.deliveryValidity')" min-width="135"><template #default="{row}">{{ row.leadTime?`${row.leadTime} ${t('sourcingDetail.days')}`:'—' }}<small>{{ row.validUntil||t('sourcingDetail.noDeadline') }}</small></template></el-table-column>
                  <el-table-column :label="t('sourcingDetail.managerDecision')" min-width="220"><template #default="{row}"><strong>{{ t('sourcingDetail.reason') }}: {{ row.reason||'—' }}</strong><small>{{ t('sourcingDetail.risk') }}: {{ row.risk||t('sourcingDetail.none') }}</small></template></el-table-column>
                </el-table>
                <footer><span>确认人：{{ plan.confirmedByName||'—' }} · {{ formatTime(plan.confirmedAt) }}</span><span v-if="plan.submittedToSalesAt">提交于 {{ formatTime(plan.submittedToSalesAt) }}</span></footer>
              </section>
            </div>
            <template v-if="!isSalesView">
              <div class="section-head rework-head"><div><h3>补充询价与重新议价任务</h3><p>精确退回到原报价采购员，或向全部采购发布新增供应商任务。</p></div></div>
              <el-empty v-if="!procurementReworks.length" description="暂无退回或补充任务" :image-size="60"/>
              <el-table v-else :data="procurementReworks" border :row-class-name="reworkRowClass"><el-table-column label="要求" width="135"><template #default="{row}">{{ reworkTypeLabel(row.requestType) }}</template></el-table-column><el-table-column label="范围" min-width="180"><template #default="{row}"><strong>{{ row.productName||'全部产品' }}</strong><small>{{ row.supplierName||'新增供应商' }} · {{ row.assignedBuyerName||'全部采购可处理' }}</small></template></el-table-column><el-table-column prop="reason" label="原因" min-width="240"/><el-table-column label="状态" width="150"><template #default="{row}"><el-tag :type="reworkStatus(row).type">{{ reworkStatus(row).label }}</el-tag></template></el-table-column><el-table-column label="处理结果" min-width="180"><template #default="{row}">{{ row.resolutionNote||'—' }}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button v-if="canResolveRework(row)" link type="primary" @click="resolveRework(row)">完成任务</el-button><span v-else-if="row.status==='OPEN'" class="muted-action">无操作权限</span></template></el-table-column></el-table>
            </template>
          </el-tab-pane>

          <el-tab-pane v-if="isSalesView" :label="t('sourcingDetail.tabs.negotiation')" name="negotiation">
            <div class="section-head"><div><h2>{{ t('sourcingDetail.negotiationTitle') }}</h2><p>{{ t('sourcingDetail.negotiationHint') }}</p></div><div class="handoff-actions"><el-button :disabled="!salesPlans.length" @click="openSalesProcurementRework()">{{ t('sourcingDetail.addSupplier') }}</el-button><el-button :disabled="!salesPlans.length" @click="openSalesShippingRework()">{{ t('sourcingDetail.addCarrier') }}</el-button><el-button type="primary" :disabled="!submittedProcurementPlans.length" @click="openSalesPlan">{{ t('sourcingDetail.createCustomerPlan') }}</el-button></div></div>
            <el-empty v-if="!salesPlans.length" :description="t('sourcingDetail.noCustomerPlan')" />
            <div v-else>
              <div v-if="salesPlans.length>1" class="version-fold-actions"><span>{{ t('sourcingDetail.previousVersions',{count:salesPlans.length-1}) }}</span><div><el-button link @click="expandAllSalesPlans">{{ t('sourcingDetail.expandAll') }}</el-button><el-button link @click="collapseHistoricalSalesPlans">{{ t('sourcingDetail.collapseAll') }}</el-button></div></div>
              <div class="manager-plan-list">
              <section v-for="plan in salesPlans" :key="plan.id" class="manager-plan-card sales-plan-card" :class="{'sales-plan-card--collapsed':!isSalesPlanExpanded(plan)}">
                <header><div><small>{{ t('sourcingDetail.communicationPlan',{plan:plan.versionNo,requirement:plan.requirementVersionNo}) }}</small><h3>{{ plan.planNo }}</h3><p>{{ t('sourcingDetail.customerNote') }}: {{ plan.customerNote || '—' }}</p></div><div class="manager-plan-actions"><el-tag :type="plan.status==='PRESENTED'?'success':plan.status==='REWORK_REQUESTED'?'warning':'info'">{{ salesPlanStatusLabel(plan.status) }}</el-tag><small>{{ t('sourcingDetail.validUntil') }} {{ plan.validUntil }}</small><el-button link type="primary" @click="toggleSalesPlan(plan)">{{ t(isSalesPlanExpanded(plan)?'sourcingDetail.collapse':'sourcingDetail.expand') }}</el-button></div></header>
                <div v-show="isSalesPlanExpanded(plan)" class="sales-plan-body">
                <el-table :data="plan.items" border>
                  <el-table-column :label="t('sourcingDetail.product')" min-width="145"><template #default="{row}">{{ localizedLineProduct(row.sourcingLineId,row.productName) }}</template></el-table-column>
                  <el-table-column :label="t('sourcingDetail.salesPlanDialog.supplierOption')" min-width="180"><template #default="{row}"><strong>{{ row.supplierName }}</strong><small>{{ row.factoryName || '—' }}</small></template></el-table-column>
                  <el-table-column :label="t('sourcingDetail.option')" width="100"><template #default="{row}"><el-tag :type="row.optionType==='PRIMARY'?'success':'info'">{{ t(row.optionType==='PRIMARY'?'sourcingDetail.primary':'sourcingDetail.alternative') }} {{ row.priority }}</el-tag></template></el-table-column>
                  <el-table-column :label="t('sourcingDetail.customerUnitPrice')" min-width="150"><template #default="{row}"><strong>{{ row.customerCurrency }} {{ row.customerUnitPrice }}/{{ row.uomCode }}</strong><small>{{ row.quotedQty }} {{ row.uomCode }}</small></template></el-table-column>
                  <el-table-column prop="promisedDeliveryDate" :label="t('sourcingDetail.promisedDelivery')" width="125"/>
                  <el-table-column prop="lineNote" :label="t('sourcingDetail.customerRemark')" min-width="160"/>
                  <el-table-column :label="t('sourcingDetail.returnUnsatisfied')" width="120"><template #default="{row}"><el-button link type="warning" @click="openSalesProcurementRework(plan,row)">{{ t('sourcingDetail.returnProcurement') }}</el-button></template></el-table-column>
                </el-table>
                <div v-if="plan.shippingOptions?.length" class="plan-shipping-options"><strong>{{ t('sourcingDetail.salesPlanDialog.shippingCandidates') }}</strong><div v-for="ship in plan.shippingOptions" :key="ship.id"><span>{{ ship.carrierForwarder }} · {{ ship.serviceOptionName || '—' }}</span><span>{{ ship.customerCurrency }} {{ ship.customerFreightAmount }}</span><span>{{ ship.portOfLoading || '—' }} → {{ ship.portOfDischarge || '—' }}</span><span>{{ ship.estimatedDeparture || '—' }} → {{ ship.estimatedArrival || '—' }}</span><el-button link type="warning" @click="openSalesShippingReworkOption(plan,ship)">{{ t('sourcingDetail.returnShipping') }}</el-button></div></div>
                <footer><span>{{ t('sourcingDetail.internalNote') }}: {{ plan.internalNote || '—' }}</span><span>{{ formatTime(plan.presentedAt) }}</span></footer>
                </div>
              </section>
              </div>
            </div>
            <div class="section-head rework-head"><div><h3>{{ t('sourcingDetail.customerSelectionTitle') }}</h3><p>{{ t('sourcingDetail.customerSelectionHint') }}</p></div><el-button type="success" :disabled="!activeCustomerSelectionPlan" @click="activeCustomerSelectionPlan&&openCustomerSelection(activeCustomerSelectionPlan)">{{ t('sourcingDetail.confirmCustomerSelection') }}</el-button></div>
            <el-alert v-if="!activeCustomerSelectionPlan" type="warning" show-icon :closable="false" :title="customerSelectionBlockedHint" class="selection-blocked-alert"/>
            <el-empty v-if="!customerSelections.length" :description="t('sourcingDetail.noCustomerSelection')" :image-size="55"/>
            <div v-else>
              <div v-if="customerSelections.length>1" class="version-fold-actions"><span>{{ t('sourcingDetail.previousSelections',{count:customerSelections.length-1}) }}</span><div><el-button link @click="expandAllCustomerSelections">{{ t('sourcingDetail.expandAll') }}</el-button><el-button link @click="collapseHistoricalCustomerSelections">{{ t('sourcingDetail.collapseAll') }}</el-button></div></div>
              <div class="selection-history">
              <section v-for="selection in customerSelections" :key="selection.id" class="selection-card" :class="[`selection-card--${String(selection.status).toLowerCase()}`,{'selection-card--collapsed':!isCustomerSelectionExpanded(selection)}]">
                <header><div><strong>{{ selection.selectionNo }} · V{{ selection.versionNo }}</strong><small>{{ selection.customerContact || t('sourcingDetail.missingContact') }} · {{ formatTime(selection.customerConfirmedAt) }}</small></div><div class="selection-card-actions"><el-button v-if="selection.status==='CUSTOMER_CONFIRMED'&&canCreateQuotation" type="primary" size="small" :loading="saving" @click="createFormalQuotation(selection)">{{ t('sourcingDetail.createFormalQuotation') }}</el-button><el-tag :type="customerSelectionStatus(selection.status).type">{{ customerSelectionStatus(selection.status).label }}</el-tag><el-button link type="primary" @click="toggleCustomerSelection(selection)">{{ t(isCustomerSelectionExpanded(selection)?'sourcingDetail.collapse':'sourcingDetail.expand') }}</el-button></div></header>
                <div v-show="isCustomerSelectionExpanded(selection)" class="selection-card-body">
                <div class="selection-items"><div v-for="item in selection.items" :key="item.id"><strong>{{ localizedLineProduct(item.sourcingLineId,item.productName) }}</strong><span>{{ item.supplierName }} · {{ item.factoryName || '—' }}</span><span>{{ item.customerCurrency }} {{ item.customerUnitPrice }}/{{ item.uomCode }} · {{ item.confirmedQty }} {{ item.uomCode }}</span><span v-if="item.customerManagedShipping">{{ t('sourcingDetail.customerManagedShipping') }}</span><span v-if="item.finalCustomerUnitPrice">{{ t('sourcingDetail.finalCustomerPrice') }}: {{ item.finalCustomerCurrency }} {{ item.finalCustomerUnitPrice }}/{{ item.uomCode }}</span><span v-if="item.finalCustomerPaymentTerms">{{ t('sourcingDetail.paymentTerms') }}: {{ item.finalCustomerPaymentTerms }} · {{ t('sourcingDetail.incoterm') }}: {{ item.finalCustomerIncoterm }} · {{ t('sourcingDetail.customerRequiredDate') }}: {{ item.finalCustomerRequiredDate }}</span></div><div v-for="shipment in selection.shipments||[]" :key="`ship-${shipment.id}`"><strong>{{ shipment.carrierForwarder }} · {{ shipment.serviceOptionName || '—' }}</strong><span>{{ shipment.customerCurrency }} {{ shipment.customerFreightAmount }} · {{ shipment.portOfLoading || '—' }} → {{ shipment.portOfDischarge || '—' }}</span><span>{{ shipment.estimatedDeparture || '—' }} → {{ shipment.estimatedArrival || '—' }}</span><span v-if="shipment.finalCustomerFreightAmount">{{ t('sourcingDetail.finalCustomerFreight') }}: {{ shipment.finalCustomerCurrency }} {{ shipment.finalCustomerFreightAmount }}</span></div></div>
                <div v-if="selection.recheckTasks?.length" class="recheck-results"><strong>{{ t('sourcingDetail.recheckResults') }}</strong><div v-for="task in selection.recheckTasks" :key="task.id" class="recheck-result"><span><el-tag size="small" :type="task.status==='RESOLVED'?'success':'warning'">{{ task.taskDomain==='SHIPPING'?t('sourcingDetail.shippingRecheck'):t('sourcingDetail.procurementRecheck') }}</el-tag> {{ task.productName||task.carrierForwarder||'—' }}</span><span v-if="task.status==='RESOLVED'&&task.taskDomain==='PROCUREMENT'">{{ task.finalCurrency }} {{ task.finalUnitPrice }} · {{ task.finalAvailableQty }} · {{ task.finalLeadTime }} {{ t('sourcingDetail.days') }} · {{ task.finalIncoterm }} · {{ task.finalPaymentTerms }} · {{ task.finalValidUntil }}</span><span v-else-if="task.status==='RESOLVED'">{{ task.finalCurrency }} {{ task.finalFreightAmount }} · {{ task.finalEstimatedDeparture }} → {{ task.finalEstimatedArrival }} · {{ task.finalValidUntil }}</span><span v-else>{{ t('sourcingDetail.awaitingRecheck') }}</span><small v-if="task.resolutionNote">{{ task.resolvedByName||'—' }}: {{ task.resolutionNote }}</small></div></div>
                <div v-if="selection.status==='AWAITING_CUSTOMER_CONFIRMATION'" class="customer-decision-actions"><el-button type="success" @click="openCustomerDecision(selection,true)">{{ t('sourcingDetail.customerAccept') }}</el-button><el-button type="danger" plain @click="openCustomerDecision(selection,false)">{{ t('sourcingDetail.customerReject') }}</el-button></div>
                <footer><span v-if="selection.status==='INVALIDATED'">{{ t('sourcingDetail.invalidatedReason') }}: {{ selection.invalidatedReason || '—' }}</span><span v-else-if="selection.status==='CUSTOMER_REJECTED'">{{ t('sourcingDetail.customerDecisionNote') }}: {{ selection.customerDecisionNote||'—' }}</span><span v-else>{{ t('sourcingDetail.finalRecheckProgress',{done:resolvedRecheckCount(selection),total:(selection.recheckTasks||[]).length}) }}</span><span>{{ selection.confirmationNote || '—' }}</span></footer>
                </div>
              </section>
              </div>
            </div>
            <div class="section-head rework-head"><div><h3>{{ t('sourcingDetail.communicationRecords') }}</h3><p>{{ t('sourcingDetail.communicationHint') }}</p></div><el-button type="primary" plain :disabled="!salesPlans.length" @click="openFeedback">{{ t('sourcingDetail.recordFeedback') }}</el-button></div>
            <el-empty v-if="!customerFeedback.length" :description="t('sourcingDetail.noCommunication')" :image-size="55"/>
            <el-timeline v-else><el-timeline-item v-for="item in customerFeedback" :key="item.id" :timestamp="formatTime(item.contactedAt)" placement="top"><div class="change"><strong>{{ feedbackResultLabel(item.result) }} · {{ item.contactName || t('sourcingDetail.missingContact') }}</strong><p>{{ feedbackChannelLabel(item.channel) }} · {{ item.summary }}</p><p>{{ t('sourcingDetail.recordedBy') }}: {{ item.createdByName }}</p></div></el-timeline-item></el-timeline>
          </el-tab-pane>

          <el-tab-pane v-if="!isSalesView" label="成本方案" name="costs">
            <div class="section-head"><div><h2>成本与利润方案</h2><p>汇总采购成本、运输与其他费用，形成可确认、可追溯的客户报价依据。</p></div><el-button v-if="canPrice&&confirmedQuoteLines.length&&canStartCostVersion" type="primary" plain @click="openCostScenario">新建成本方案</el-button></div>
            <el-alert v-if="rejectedQuote" type="warning" :closable="false" show-icon style="margin-bottom:12px" :title="`客户已拒绝报价单 ${rejectedQuote.quoteNo}${rejectedQuote.respondNote?`：${rejectedQuote.respondNote}`:''}`"/>
            <el-table :data="costs" @row-click="openCostDetail"><el-table-column label="版本链路" width="230"><template #default="{row}"><strong>需求 V{{ row.requirementVersionNo || 1 }} → 成本 C{{ row.versionNo || 1 }}</strong><small>{{ row.scenarioNo }}</small></template></el-table-column><el-table-column prop="currency" label="币种" width="80"/><el-table-column prop="productTotal" label="产品成本"/><el-table-column prop="chargeTotal" label="费用"/><el-table-column prop="customerTotal" label="报价金额"/><el-table-column label="交接状态" width="125"><template #default="{row}"><el-tag :type="row.submittedToSalesAt?'success':'info'">{{ row.submittedToSalesAt?'已提交销售':costScenarioPresentation(row).label }}</el-tag></template></el-table-column><el-table-column label="报价单状态" width="135"><template #default="{row}"><el-tag :type="customerQuotationPresentation(row).type">{{ customerQuotationPresentation(row).label }}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="{row}"><el-button v-if="canApprove&&row.status==='DRAFT'&&canStartCostVersion" link type="success" @click.stop="confirmCostScenario(row)">确认方案</el-button><el-button v-else-if="canApprove&&row.status==='CONFIRMED'&&!row.submittedToSalesAt&&Number(row.customerQuotationId||0)===0" link type="primary" @click.stop="submitCostToSales(row)">提交销售</el-button></template></el-table-column></el-table>
          </el-tab-pane>

          <el-tab-pane v-if="isSalesView" :label="t('sourcingDetail.tabs.customerQuote')" name="customerQuote">
            <div class="section-head"><div><h2>{{ t('sourcingDetail.quoteTitle') }}</h2><p>{{ t('sourcingDetail.quoteHint') }}</p></div></div>
            <QuotationsPage embedded :quotation-ids="customerQuotationIds" :source-sourcing-case-id="id" :refresh-token="quotationRefreshToken" />
          </el-tab-pane>

          <el-tab-pane :label="t('sourcingDetail.tabs.changes')" name="changes">
            <div class="section-head"><div><h2>{{ t('sourcingDetail.changesTitle') }}</h2><p>{{ t('sourcingDetail.changesHint') }}</p></div></div>
            <el-timeline><el-timeline-item v-for="item in changes" :key="item.id" :timestamp="formatTime(item.createdAt)" placement="top"><div class="change"><strong>{{ item.summary }}</strong><p>{{ item.operatorName||t('sourcingDetail.system') }} · {{ item.section }} / {{ item.action }}</p><p v-if="item.reason">{{ t('sourcingDetail.reason') }}: {{ item.reason }}</p></div></el-timeline-item></el-timeline>
            <el-empty v-if="!changes.length" :description="t('sourcingDetail.noChanges')" />
          </el-tab-pane>
        </el-tabs>
      </section>
    </template>

    <el-dialog v-model="rfqOpen" title="新建工厂询价" width="680px"><el-alert type="info" :closable="false" title="选择你准备询价的供应商或工厂。电话、邮件、微信等人工沟通过程不需要录入系统。"/><el-form class="rfq-form" label-width="120px"><el-form-item label="供应商 / 工厂" required><SupplierFactorySelect v-model:supplier-id="rfq.supplierId" v-model:factory-id="rfq.factoryId" factory-optional @factory-selected="factorySelected"/></el-form-item><div class="factory-optional-hint">仅在已明确实际生产工厂时选择；向贸易商或供应商总部询价可以留空。</div><el-form-item label="报价币种" required><el-input v-model="rfq.currency" maxlength="3" placeholder="例如 USD" @input="rfq.currency=String(rfq.currency).toUpperCase()"/></el-form-item><el-form-item label="询价产品"><div class="rfq-products"><el-tag v-for="line in rfqEligibleLines" :key="line.id" effect="plain">{{ line.extracted.product }}</el-tag></div></el-form-item></el-form><template #footer><el-button @click="rfqOpen=false">取消</el-button><el-button type="primary" @click="createRFQ">创建工厂询价</el-button></template></el-dialog>

    <el-dialog v-model="quoteOpen" title="录入工厂正式报价" width="1040px">
      <el-alert type="info" :closable="false" title="保存即表示员工已核实该报价。再次保存会生成新版本，比较页始终只使用最新版本；计量单位来自已审核询盘。"/>
      <el-form class="dialog-form quote-meta-grid" label-width="104px">
        <el-form-item label="币种"><el-input v-model="quoteForm.currency"/></el-form-item>
        <el-form-item label="报价日期"><el-date-picker v-model="quoteForm.quotedAt" value-format="YYYY-MM-DD"/></el-form-item>
        <el-form-item label="有效期至"><el-date-picker v-model="quoteForm.validUntil" value-format="YYYY-MM-DD"/></el-form-item>
        <el-form-item label="交期"><el-select v-model="quoteForm.delivery" filterable allow-create default-first-option clearable placeholder="选择或输入交期"><el-option v-for="item in deliveryOptions" :key="item" :label="item" :value="item"/></el-select></el-form-item>
        <el-form-item label="贸易条款"><el-select v-model="quoteIncoterm" filterable allow-create default-first-option clearable placeholder="选择或输入贸易条款"><el-option v-for="item in incotermOptions" :key="item" :label="item" :value="item"/></el-select></el-form-item>
        <el-form-item label="本次付款条件"><el-select v-model="quoteForm.paymentTerms" filterable allow-create default-first-option clearable placeholder="选择已有条件，或直接输入后按回车"><el-option v-for="item in paymentTermOptions" :key="item" :label="item" :value="item"/></el-select></el-form-item>
      </el-form>
      <el-table :data="quoteRows" border><el-table-column prop="product" label="产品" min-width="170"/><el-table-column label="可供量" min-width="155"><template #default="{row}"><el-input v-model="row.qty" inputmode="decimal"><template #append>{{ row.uom }}</template></el-input></template></el-table-column><el-table-column label="单价（未报价可留空）" min-width="205"><template #default="{row}"><el-input v-model="row.unitPrice" inputmode="decimal" clearable><template #append>{{ quoteForm.currency || 'USD' }}/{{ row.uom }}</template></el-input></template></el-table-column><el-table-column label="MOQ（最小起订量）" min-width="185"><template #default="{row}"><el-input v-model="row.moq" inputmode="decimal"><template #append>{{ row.uom }}</template></el-input></template></el-table-column><el-table-column label="生产周期" min-width="145"><template #default="{row}"><el-input v-model="row.leadTime" inputmode="numeric"><template #append>天</template></el-input></template></el-table-column></el-table>
      <template #footer><el-button @click="quoteOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveQuote">保存正式报价</el-button></template>
    </el-dialog>

    <el-dialog v-model="quoteHistoryOpen" :title="quoteHistoryTitle" width="900px">
      <el-alert type="info" :closable="false" title="历史版本仅供追溯，产品组比较始终使用该采购、供应商和产品的最新版本。"/>
      <el-table :data="quoteHistoryRows" style="margin-top:14px"><el-table-column label="版本" width="90"><template #default="{row}">V{{ row.versionNo||1 }}</template></el-table-column><el-table-column prop="createdByName" label="报价人" width="120"/><el-table-column prop="supplierQuoteNo" label="报价编号" width="180"/><el-table-column label="单价" width="150"><template #default="{row}">{{ row.currency }} {{ row.unitPrice }}</template></el-table-column><el-table-column prop="qty" label="可供量" width="110"/><el-table-column prop="moq" label="MOQ" width="100"/><el-table-column prop="leadTime" label="生产周期" width="110"/><el-table-column prop="incoterm" label="贸易条款" width="110"/><el-table-column prop="validUntil" label="有效期" width="120"/></el-table>
    </el-dialog>

    <el-dialog v-model="importOpen" title="导入工厂报价 Excel" width="650px">
      <el-alert type="info" :closable="false" title="请使用本 RFQ 下载的报价模板，不要修改 RFQ 编号、行 ID、数量或单位。"/>
      <el-form label-width="110px" class="dialog-form">
        <el-form-item label="报价文件" required><input type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" @change="selectQuoteFile"/></el-form-item>
        <el-form-item label="币种"><el-input v-model="importForm.currency" maxlength="3"/></el-form-item>
        <el-form-item label="报价日期"><el-date-picker v-model="importForm.quotedAt" value-format="YYYY-MM-DD"/></el-form-item>
        <el-form-item label="有效期至"><el-date-picker v-model="importForm.validUntil" value-format="YYYY-MM-DD"/></el-form-item>
        <el-form-item label="交期"><el-select v-model="importForm.delivery" filterable allow-create default-first-option clearable placeholder="选择或输入交期"><el-option v-for="item in deliveryOptions" :key="item" :label="item" :value="item"/></el-select></el-form-item>
        <el-form-item label="本次付款条件"><el-select v-model="importForm.paymentTerms" filterable allow-create default-first-option clearable placeholder="选择已有条件，或直接输入后按回车" style="width:100%"><el-option v-for="item in paymentTermOptions" :key="item" :label="item" :value="item"/></el-select></el-form-item>
      </el-form>
      <template #footer><el-button @click="importOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="importQuote">导入报价</el-button></template>
    </el-dialog>

    <el-dialog v-model="procurementPlanOpen" title="生成经理统一采购方案" width="min(1280px,96vw)">
      <el-alert type="info" :closable="false" title="每个产品至少选择一个推荐报价，也可以保留多个推荐或备选。系统沿用客户需求和供应商可供量，经理不填写采购数量。"/>
      <el-form label-width="90px" class="dialog-form"><el-form-item label="经理意见" required><el-input v-model="procurementPlanForm.managerNote" type="textarea" :rows="2" maxlength="500" show-word-limit placeholder="说明整体选择逻辑、供应稳定性或需要销售关注的事项"/></el-form-item></el-form>
