    <el-dialog v-model="procurementReworkOpen" :title="t(reworkForm.supplierQuoteLineId?'sourcingDetail.rework.returnProcurement':'sourcingDetail.rework.addSupplier')" width="580px"><el-alert type="warning" :closable="false" :title="reworkTargetText"/><el-form label-width="100px" class="dialog-form"><el-form-item v-if="!reworkForm.supplierQuoteLineId" :label="t('sourcingDetail.rework.product')"><el-select v-model="reworkForm.sourcingLineId" clearable :placeholder="t('sourcingDetail.rework.allProducts')" style="width:100%"><el-option v-for="line in rfqEligibleLines" :key="line.id" :value="line.id" :label="localizedProductName(line)"/></el-select></el-form-item><el-form-item :label="t('sourcingDetail.rework.requirement')"><el-input :model-value="procurementReworkRequestLabel" disabled/></el-form-item><el-form-item :label="t('sourcingDetail.rework.reason')" required><el-input v-model="reworkForm.reason" type="textarea" :rows="3" maxlength="300" show-word-limit/></el-form-item></el-form><template #footer><el-button @click="procurementReworkOpen=false">{{ t('sourcingDetail.cancel') }}</el-button><el-button type="primary" :loading="saving" @click="createProcurementRework">{{ t('sourcingDetail.rework.publish') }}</el-button></template></el-dialog>

    <el-dialog v-model="costOpen" title="新建成本方案" width="min(1100px,95vw)"><el-form inline><el-form-item label="方案币种"><el-input v-model="costForm.currency" maxlength="3" style="width:90px"/></el-form-item><el-form-item label="附加费用分摊方式"><el-select v-model="costForm.allocationBasis" style="width:170px"><el-option value="TONS" label="按吨数"/><el-option value="PRODUCT_AMOUNT" label="按产品金额"/></el-select></el-form-item><el-form-item label="利润计算方式"><el-select v-model="costForm.marginType" style="width:170px"><el-option value="PERCENT" label="按成本百分比"/><el-option value="FIXED_PER_TON" label="每吨固定利润"/></el-select></el-form-item><el-form-item :label="costForm.marginType==='PERCENT'?'利润率（%）':`每吨利润（${costForm.currency||'币种'}/吨）`"><el-input v-model="costForm.marginValue" style="width:110px" :placeholder="costForm.marginType==='PERCENT'?'例如：8':'例如：20'"/></el-form-item><el-form-item v-if="submittedShippingPlans.length" label="导入船运方案"><el-select v-model="costShippingOptionId" clearable placeholder="选择经理统一方案" style="width:290px" @change="importShippingCharge"><el-option v-for="item in submittedShippingPlans" :key="item.id" :value="item.id" :label="`${item.planNo} · V${item.versionNo || 1}`"/></el-select></el-form-item></el-form><h4>为每条产品选择工厂报价</h4><el-table :data="costSelections" border><el-table-column prop="lineNo" label="产品行" width="90"/><el-table-column prop="product" label="产品" min-width="170"/><el-table-column label="选中报价" min-width="430"><template #default="{row}"><el-select v-model="row.quoteLineId" style="width:100%"><el-option v-for="item in quotesForLine(row.sourcingLineId)" :key="item.quoteLineId" :value="item.quoteLineId" :label="`${item.supplierName} · ${item.currency} ${item.unitPrice} × ${item.qty}`"/></el-select></template></el-table-column></el-table><div class="section-head cost-head"><div><h4>附加费用</h4><small>可以导入船运参考方案，或选择“自定义费用”填写公司自己的费用名称。</small></div><el-button @click="addCharge">添加费用</el-button></div><el-table :data="costCharges" border><el-table-column label="费用类型" width="240"><template #default="{row}"><div class="charge-type-editor"><el-select v-model="row.chargeType" placeholder="选择费用类型"><el-option v-for="item in chargeTypes" :key="item" :value="item" :label="chargeTypeLabel(item)"/></el-select><el-input v-if="row.chargeType==='OTHER'" v-model="row.customChargeName" maxlength="50" placeholder="输入具体费用名称"/></div></template></el-table-column><el-table-column label="计费方式" width="160"><template #default="{row}"><el-select v-model="row.basis"><el-option v-for="item in chargeBases" :key="item" :value="item" :label="chargeBasisLabel(item)"/></el-select></template></el-table-column><el-table-column label="金额" width="130"><template #default="{row}"><el-input v-model="row.amount"/></template></el-table-column><el-table-column label="币种" width="100"><template #default="{row}"><el-input v-model="row.currency"/></template></el-table-column><el-table-column label="来源"><template #default="{row}"><el-input v-model="row.source"/></template></el-table-column><el-table-column label="操作" width="80"><template #default="{$index}"><el-button link type="danger" @click="costCharges.splice($index,1)">删除</el-button></template></el-table-column></el-table><template #footer><el-button @click="costOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="createCostScenario">创建方案</el-button></template></el-dialog>

    <el-dialog v-model="costDetailOpen" title="成本方案详情" width="860px"><el-descriptions v-if="costDetail" :column="3" border><el-descriptions-item label="方案版本">V{{ costDetail.versionNo || 1 }} · {{ costDetail.scenarioNo }}</el-descriptions-item><el-descriptions-item label="状态"><el-tag :type="costScenarioPresentation(costDetail).type">{{ costScenarioPresentation(costDetail).label }}</el-tag></el-descriptions-item><el-descriptions-item label="币种">{{ costDetail.currency }}</el-descriptions-item><el-descriptions-item label="产品成本">{{ costDetail.productTotal }}</el-descriptions-item><el-descriptions-item label="附加费用">{{ costDetail.chargeTotal }}</el-descriptions-item><el-descriptions-item label="落地成本">{{ costDetail.landedTotal }}</el-descriptions-item><el-descriptions-item label="利润">{{ costDetail.marginTotal }}</el-descriptions-item><el-descriptions-item label="客户报价" :span="2"><strong>{{ costDetail.currency }} {{ costDetail.customerTotal }}</strong></el-descriptions-item><el-descriptions-item v-if="costDetail.confirmReason" label="中标原因" :span="3">{{ costDetail.confirmedByName }}：{{ costDetail.confirmReason }}</el-descriptions-item></el-descriptions><h4 v-if="costDetail?.charges?.length" style="margin:14px 0 6px">附加费用明细</h4><el-table v-if="costDetail?.charges?.length" :data="costDetail.charges" size="small"><el-table-column label="费用类型" min-width="140"><template #default="{row}">{{ chargeTypeLabels[row.chargeType]||row.chargeType }}<span v-if="row.description">（{{ row.description }}）</span></template></el-table-column><el-table-column label="计费方式" width="110"><template #default="{row}">{{ chargeBasisLabels[row.basis]||row.basis }}</template></el-table-column><el-table-column label="原币金额" width="130" align="right"><template #default="{row}">{{ row.currency }} {{ row.amount }}</template></el-table-column><el-table-column label="折算金额" width="130" align="right"><template #default="{row}">{{ row.convertedAmount }}</template></el-table-column></el-table><h4 style="margin:14px 0 6px">产品明细</h4><el-table :data="costDetail?.lines||[]" size="small"><el-table-column prop="productName" label="产品"/><el-table-column prop="supplierName" label="供应商"/><el-table-column prop="landedCost" label="落地成本" align="right"/><el-table-column prop="customerAmount" label="客户金额" align="right"/></el-table></el-dialog>

    <el-dialog v-model="customerMapOpen" title="关联内部客户" width="520px"><el-alert type="info" :closable="false" title="该询盘尚未关联内部客户档案，请先选择客户。"/><el-select v-model="mappedCustomerId" filterable style="width:100%;margin-top:16px"><el-option v-for="item in customers" :key="item.id" :value="item.id" :label="`${item.code} · ${item.name}`"/></el-select><template #footer><el-button @click="customerMapOpen=false">取消</el-button><el-button type="primary" @click="submitMappedCustomer">继续生成报价</el-button></template></el-dialog>
