      <h3 class="dialog-subtitle">{{ t('sourcingDetail.salesPlanDialog.productCandidates') }}</h3>
      <el-table :data="salesPlanRows" :row-class-name="salesPlanRowClass" border max-height="330"><el-table-column :label="t('sourcingDetail.salesPlanDialog.include')" width="78"><template #default="{row}"><el-checkbox v-model="row.selected" @change="salesPlanSelectionChanged(row)"/><small v-if="!row.selected" class="excluded-label">{{ t('sourcingDetail.salesPlanDialog.excluded') }}</small></template></el-table-column><el-table-column :label="t('sourcingDetail.product')" min-width="130"><template #default="{row}">{{ localizedLineProduct(row.sourcingLineId,row.productName) }}</template></el-table-column><el-table-column :label="t('sourcingDetail.salesPlanDialog.supplierOption')" min-width="190"><template #default="{row}"><strong>{{ row.supplierName }}</strong><small>{{ row.factoryName || '—' }} · {{ row.incoterm || '—' }} · {{ row.paymentTerms || '—' }}</small></template></el-table-column><el-table-column :label="t('sourcingDetail.salesPlanDialog.type')" width="115"><template #default="{row}"><el-select v-model="row.optionType" :disabled="!row.selected"><el-option value="PRIMARY" :label="t('sourcingDetail.primary')"/><el-option value="ALTERNATIVE" :label="t('sourcingDetail.alternative')"/></el-select></template></el-table-column><el-table-column :label="t('sourcingDetail.salesPlanDialog.order')" width="85"><template #default="{row}"><el-input-number v-model="row.priority" :disabled="!row.selected" :min="1" controls-position="right"/></template></el-table-column><el-table-column :label="t('sourcingDetail.salesPlanDialog.suggestedPrice')" min-width="235"><template #default="{row}"><div class="price-input"><el-input v-model="row.customerCurrency" :disabled="!row.selected" maxlength="3"/><el-input v-model="row.customerUnitPrice" :disabled="!row.selected" :placeholder="t('sourcingDetail.salesPlanDialog.autoPrice')"/></div><small v-if="row.selected" class="price-source">{{ row.priceSource }}</small></template></el-table-column><el-table-column :label="t('sourcingDetail.salesPlanDialog.promisedDelivery')" width="145"><template #default="{row}"><el-date-picker v-model="row.promisedDeliveryDate" :disabled="!row.selected" value-format="YYYY-MM-DD" style="width:130px"/></template></el-table-column><el-table-column :label="t('sourcingDetail.salesPlanDialog.note')" min-width="150"><template #default="{row}"><el-input v-model="row.lineNote" :disabled="!row.selected"/></template></el-table-column></el-table>
