    <el-dialog v-model="feedbackOpen" :title="t('sourcingDetail.feedbackDialog.title')" width="620px"><el-form class="dialog-form" label-width="100px"><el-form-item :label="t('sourcingDetail.feedbackDialog.plan')" required><el-select v-model="feedbackForm.salesPlanId"><el-option v-for="item in salesPlans" :key="item.id" :value="item.id" :label="`${item.planNo} · V${item.versionNo}`"/></el-select></el-form-item><el-form-item :label="t('sourcingDetail.feedbackDialog.time')" required><el-date-picker v-model="feedbackForm.contactedAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ"/></el-form-item><el-form-item :label="t('sourcingDetail.feedbackDialog.contact')"><el-select v-model="feedbackForm.contactName" filterable allow-create default-first-option clearable :placeholder="t('sourcingDetail.feedbackDialog.contactPlaceholder')" style="width:100%"><el-option v-for="contact in customerContacts" :key="contact.id" :value="contact.name" :label="contactLabel(contact)"/></el-select><small class="field-help">{{ t('sourcingDetail.feedbackDialog.contactHint') }}</small></el-form-item><el-form-item :label="t('sourcingDetail.feedbackDialog.channel')"><el-select v-model="feedbackForm.channel"><el-option value="PHONE" :label="t('sourcingDetail.feedbackDialog.phone')"/><el-option value="EMAIL" :label="t('sourcingDetail.feedbackDialog.email')"/><el-option value="MEETING" :label="t('sourcingDetail.feedbackDialog.meeting')"/><el-option value="OTHER" :label="t('sourcingDetail.feedbackDialog.other')"/></el-select></el-form-item><el-form-item :label="t('sourcingDetail.feedbackDialog.result')"><el-select v-model="feedbackForm.result"><el-option value="CONTINUE_NEGOTIATION" :label="t('sourcingDetail.feedbackDialog.continue')"/><el-option value="REQUOTE_REQUIRED" :label="t('sourcingDetail.feedbackDialog.requote')"/><el-option value="COMMENT" :label="t('sourcingDetail.feedbackDialog.comment')"/></el-select></el-form-item><el-form-item :label="t('sourcingDetail.feedbackDialog.summary')" required><el-input v-model="feedbackForm.summary" type="textarea" :rows="4" maxlength="500" show-word-limit/></el-form-item></el-form><template #footer><el-button @click="feedbackOpen=false">{{ t('sourcingDetail.cancel') }}</el-button><el-button type="primary" :loading="saving" @click="addCustomerFeedback">{{ t('sourcingDetail.feedbackDialog.save') }}</el-button></template></el-dialog>

    <el-dialog v-model="customerSelectionOpen" :title="t('sourcingDetail.customerSelectionDialog.title')" width="min(1180px,96vw)" top="4vh">
      <el-alert type="info" :closable="false" :title="t('sourcingDetail.customerSelectionDialog.hint')"/>
      <el-form class="dialog-form" label-width="112px"><div class="customer-selection-meta"><el-form-item :label="t('sourcingDetail.customerSelectionDialog.contact')"><el-select v-model="customerSelectionForm.customerContact" filterable allow-create default-first-option clearable style="width:100%"><el-option v-for="contact in customerContacts" :key="contact.id" :value="contact.name" :label="contactLabel(contact)"/></el-select></el-form-item><el-form-item :label="t('sourcingDetail.customerSelectionDialog.time')" required><el-date-picker v-model="customerSelectionForm.customerConfirmedAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" style="width:100%"/></el-form-item><el-form-item :label="t('sourcingDetail.customerSelectionDialog.note')"><el-input v-model="customerSelectionForm.confirmationNote" maxlength="500"/></el-form-item></div></el-form>
      <section v-for="group in customerSelectionGroups" :key="group.sourcingLineId" class="customer-selection-group"><header><div><strong>{{ localizedLineProduct(group.sourcingLineId,group.productName) }}</strong><small>{{ sourceSpecification(group.sourcingLineId) }} · {{ t('sourcingDetail.customerSelectionDialog.originalDemand') }} {{ sourceQuantity(group.sourcingLineId) }} {{ sourceUom(group.sourcingLineId) }}</small></div><small>{{ t('sourcingDetail.customerSelectionDialog.chooseOne') }}</small></header><el-radio-group v-model="customerSelectionForm.selectedByLine[String(group.sourcingLineId)]" @change="customerProductSelectionChanged(group,$event)"><el-radio :value="0">{{ t('sourcingDetail.customerSelectionDialog.notSelected') }}</el-radio><el-radio v-for="item in group.items" :key="item.id" :value="Number(item.id)"><span class="selection-option"><strong>{{ item.supplierName }} · {{ item.factoryName || t('sourcingDetail.customerSelectionDialog.unspecifiedFactory') }}</strong><span>{{ item.optionType==='PRIMARY'?t('sourcingDetail.primary'):t('sourcingDetail.alternative') }} {{ item.priority }} · {{ item.customerCurrency }} {{ item.customerUnitPrice }}/{{ item.uomCode }} · {{ t('sourcingDetail.customerSelectionDialog.maxAvailable') }} {{ item.quotedQty }} {{ item.uomCode }}</span><span>{{ item.incoterm || '—' }} · {{ item.paymentTerms || '—' }} · {{ item.supplierValidUntil || customerSelectionPlan?.validUntil || '—' }} · {{ item.promisedDeliveryDate || '—' }}</span></span></el-radio></el-radio-group><div v-if="selectedCustomerItemForGroup(group)" class="intent-quantity"><label>{{ t('sourcingDetail.customerSelectionDialog.intentQuantity') }}</label><el-input-number v-model="customerSelectionForm.confirmedQtyByLine[String(group.sourcingLineId)]" :min="0.0001" :max="Number(selectedCustomerItemForGroup(group)?.quotedQty||0)" :precision="4" :step="1"/><strong>{{ selectedCustomerItemForGroup(group)?.uomCode }}</strong><span>{{ t('sourcingDetail.customerSelectionDialog.subtotal') }}: {{ selectedCustomerItemForGroup(group)?.customerCurrency }} {{ lineSubtotal(selectedCustomerItemForGroup(group)) }}</span></div></section>
