    await loadProductDisplays()
    templateFields.value=[]
    if(Number(detail.value?.inquiryTemplateId||0)>0){const response=await get<any>(`/inquiry-templates/${detail.value?.inquiryTemplateId}`);templateFields.value=response.template?.fields||[]}
    const shippingEndpoint=isSalesView.value?`/sales-inquiries/${id}/shipping-collaboration`:`/sourcing-cases/${id}/shipping-collaboration`
    shippingCollaboration.value=await get<any>(shippingEndpoint,undefined,quietErrors).catch(()=>undefined)
    // The compact cost selector still renders one line per company. Keep its
    // display fields derived from the new multi-cargo option until T7 replaces
    // it with the customer-facing option picker.
    for(const option of shippingCollaboration.value?.options||[]){const first=option.lines?.[0]||{};option.scheduleNo=option.carrierForwarder;option.currency=first.currency||'';option.freightAmount=`${option.lines?.length||0} 种货物`;option.chargeBasis=option.estimatedArrival?`到港 ${option.estimatedArrival}`:'到港日待定'}
    await loadCaseQuotations()
  }finally{loading.value=false}
}
// 客户的答复要回到案件（B1）：报价单状态在 export 那边，采购员却在这页
// 干活——被拒了不该等他自己想起来去翻。
const caseQuotations=ref<AnyRow[]>([]),quotationRefreshToken=ref(0)
async function loadCaseQuotations(){const ids=costs.value.map(row=>Number(row.customerQuotationId||0)).filter(Boolean);if(!ids.length){caseQuotations.value=[];return}try{caseQuotations.value=(await Promise.all(ids.map(qid=>get<any>(`/quotations/${qid}`).then(r=>r.quotation).catch(()=>null)))).filter(Boolean)}catch{caseQuotations.value=[]}}
const latestCaseQuotation=computed(()=>[...caseQuotations.value].sort((a,b)=>Number(b.id)-Number(a.id))[0]||null)
const rejectedQuote=computed(()=>latestCaseQuotation.value?.status==='REJECTED'?latestCaseQuotation.value:null)
const hasAcceptedQuotation=computed(()=>caseQuotations.value.some(item=>item.status==='ACCEPTED'))
const canStartCostVersion=computed(()=>!hasAcceptedQuotation.value&&(!latestCaseQuotation.value||latestCaseQuotation.value.status==='REJECTED'))
function quotationForCost(row:AnyRow){return caseQuotations.value.find(item=>String(item.id)===String(row.customerQuotationId))}
function costScenarioPresentation(row:AnyRow){return describeCostScenario({status:String(row.status??''),customerQuotationId:row.customerQuotationId})}
function customerQuotationPresentation(row:AnyRow){const quotation=quotationForCost(row),status=String(quotation?.status||(Number(row.customerQuotationId||0)>0?'CREATED':'')),presentation=describeCustomerQuotation(quotation||(status?{status}:undefined)),key=({DRAFT:'draft',SENT:'sent',ACCEPTED:'accepted',REJECTED:'rejected',EXPIRED:'expired',CANCELLED:'cancelled',CREATED:'generated'} as Record<string,string>)[status]||(status?'generated':'notGenerated');return {...presentation,label:t(`sourcingDetail.quotationStatuses.${key}`)}}
async function loadTab(name:any){if(name==='changes'){const endpoint=isSalesView.value?`/sales-inquiries/${id}/changes`:`/sourcing-cases/${id}/changes`;changes.value=(await get<any>(endpoint)).changes||[]}}
function openPeerView(){tab.value='products';void router.push(peerPath.value)}
function quoteRfq(row:any){return rfqs.value.find(item=>String(item.id)===String(row.factoryRfqId))}function quoteFactoryName(row:any){return quoteRfq(row)?.factoryName||'未指定生产工厂'}function sourceLine(v:any){return detail.value?.lines.find((item:any)=>String(item.id)===String(v))}function sourceProduct(v:any){const line=sourceLine(v);return line?.extracted?.product||(line?`产品行 #${sourceLineNo(v)}`:'未关联产品')}function sourceQuantity(v:any){return sourceLine(v)?.extracted?.quantity||'—'}function sourceUom(v:any){return String(sourceLine(v)?.extracted?.quantityUnit||'').trim().toUpperCase()||'单位'}function sourceSpecification(v:any){return specificationSummary(sourceLine(v)?.extracted||{})}
function rfqProductSummary(row:any){const names=(row.sourcingLineIds||[]).map((lineID:any)=>sourceProduct(lineID));return names.length<=2?names.join('、')||'未指定产品':`${names.slice(0,2).join('、')} 等 ${names.length} 项`}
 const comparisonSortLabel=computed(()=>({PRICE:'按单价从低到高',LEAD_TIME:'按生产周期从短到长',MOQ:'按 MOQ 从低到高'} as Record<string,string>)[comparisonSort.value]),latestQuoteLines=computed(()=>{const latest=new Map<string,AnyRow>();for(const row of quoteLines.value){const key=[row.factoryRfqId,row.sourcingLineId].join(':');const current=latest.get(key);if(!current||Number(row.versionNo||0)>Number(current.versionNo||0)||(Number(row.versionNo||0)===Number(current.versionNo||0)&&Number(row.quoteId||0)>Number(current.quoteId||0)))latest.set(key,row)}return [...latest.values()].sort((a,b)=>Number(a.sourcingLineId)-Number(b.sourcingLineId)||Number(a.unitPrice)-Number(b.unitPrice))}),confirmedComparisonQuoteLines=computed(()=>latestQuoteLines.value.filter(row=>!isQuoteExpired(row))),comparisonQuoteGroups=computed(()=>{const groups=new Map<string,{sourcingLineId:string,rows:AnyRow[]}>();for(const line of rfqEligibleLines.value)groups.set(String(line.id),{sourcingLineId:String(line.id),rows:[]});for(const row of latestQuoteLines.value){const key=String(row.sourcingLineId);let group=groups.get(key);if(!group){group={sourcingLineId:key,rows:[]};groups.set(key,group)}group.rows.push(row)}return [...groups.values()].map(group=>({...group,rows:[...group.rows].sort(compareQuoteRows)}))})
const planSelectionGroups=computed(()=>rfqEligibleLines.value.map((line:any)=>({sourcingLineId:String(line.id),rows:planSelectionRows.value.filter(row=>String(row.sourcingLineId)===String(line.id))})))
const returnedQuoteLineIds=computed(()=>new Set(procurementReworks.value.filter(row=>['REQUOTE','RENEGOTIATE'].includes(row.requestType)).map(row=>String(row.supplierQuoteLineId))))
function isQuoteReturned(row:AnyRow){return returnedQuoteLineIds.value.has(String(row.quoteLineId))}
function activeQuoteRows(rows:AnyRow[]){return rows.filter(row=>!isQuoteReturned(row))}
const selectablePlanQuoteLines=computed(()=>confirmedComparisonQuoteLines.value.filter(row=>(row.confirmationStatus||'WRITTEN_CONFIRMED')==='WRITTEN_CONFIRMED'&&!isQuoteReturned(row)))
const reworkTargetText=computed(()=>reworkForm.supplierQuoteLineId?`退回 ${reworkForm.buyerName||'原采购员'} 负责的 ${reworkForm.supplierName||'供应商'} · ${reworkForm.productName||'产品'} 报价。原报价和历史不会删除。`:'该任务会发布给全部采购专员，可指定某个产品，也可以要求为全部产品增加供应商。')
function quoteSortValue(row:any){const raw=comparisonSort.value==='LEAD_TIME'?row.leadTime:comparisonSort.value==='MOQ'?row.moq:row.unitPrice;const value=Number(raw);return raw===''||raw===null||raw===undefined||!Number.isFinite(value)?Number.POSITIVE_INFINITY:value}
// 换算价在手时按同一把尺排序；缺汇率时退回按币种分组——绝不假装比较过。
function compareQuoteRows(a:any,b:any){if(comparisonSort.value==='PRICE'){if(a.comparePrice&&b.comparePrice)return Number(a.comparePrice)-Number(b.comparePrice)||String(a.supplierName).localeCompare(String(b.supplierName),'zh-CN');if(a.currency!==b.currency)return String(a.currency).localeCompare(String(b.currency))}return quoteSortValue(a)-quoteSortValue(b)||String(a.supplierName).localeCompare(String(b.supplierName),'zh-CN')}
function statusLabel(v:string){if(isSalesView.value)return t(`sourcing.statuses.${v}`);return ({REVIEWING:'待采购接单',SOURCING:'工厂询价中',QUOTES_RECEIVED:'报价比较中',COSTING:'成本测算中',CUSTOMER_QUOTE_CREATED:'客户报价跟踪中',CANCELLED:'已取消'} as any)[v]||v}function channelLabel(v:string){return inquiryChannels.find(x=>x.value===(v||'SYSTEM_EMAIL'))?.label||v}function confirmationLabel(v:string){return ({VERBAL_PENDING:'口头报价待确认',WRITTEN_CONFIRMED:'书面已确认',INVALID:'已失效',CANCELLED:'已取消'} as any)[v||'WRITTEN_CONFIRMED']||v}function fieldLabel(v:string){return ({product:'产品',materialStandard:'材质/标准',material_standard:'材质/标准',grade:'牌号',thickness:'厚度',width:'宽度',lengthOrForm:'长度/形式',length_or_form:'长度/形式',surfaceRequirement:'表面要求',surface_requirement:'表面要求',packaging:'包装',delivery:'交期',paymentTerms:'付款条件',payment_terms:'付款条件',incoterm:'贸易术语',port:'港口',quantityUnit:'单位',quantity_unit:'单位',quantity:'数量',remarks:'备注'} as any)[v]||v}
function isQuoteExpired(row:any){return isDateOnlyExpired(row.validUntil)}
function isDirectQuoteRFQ(row:any){return row.inquiryChannel==='OTHER'&&!row.contactEmail&&!row.contactValue&&!row.responseDueAt}
const templateProperty:Record<string,string>={material_standard:'materialStandard',length_or_form:'lengthOrForm',surface_requirement:'surfaceRequirement',coil_weight:'coilWeight',coil_id:'coilId',payment_terms:'paymentTerms',quantity_unit:'quantityUnit'}
function readTemplateField(extracted:any,key:string){if(key.startsWith('custom.'))return extracted?.customFields?.[key]||'';return extracted?.[templateProperty[key]||key]||''}
function localizedReviewField(key:string,fallback:string){const normalized=templateProperty[key]||key;return isSalesView.value&&localizedReviewFields.has(normalized)?t(`sourcing.reviewFields.${normalized}`):fallback}
const businessValueKeys:Record<string,string>={'现货':'onHand','海运包装':'seaPackaging','木箱':'woodenCrate','钢带捆扎':'steelStrap','防水纸+钢带捆扎':'waterproofStrap','防潮纸+钢带捆扎':'moistureproofStrap','六角捆扎':'hexBundle','黑皮':'blackFinish','光亮':'brightFinish','无油钝化':'unoiledPassivated','防锈油':'rustPreventiveOil','货到付款':'cashOnDelivery','预付30%，发货前付清':'prepay30','月结30天':'monthly30','月结60天':'monthly60'}
const productAliasKeys:Record<string,string>={'镀锌钢卷':'galvanizedCoil','热轧钢板':'hotRolledPlate','冷轧钢卷':'coldRolledCoil','无缝钢管':'seamlessPipe','矩形钢管':'rectangularTube','等边角钢':'equalAngle','圆钢棒':'roundBar','方钢棒':'squareBar'}
function localizedBusinessValue(value:any){const raw=String(value??'').trim();if(!raw||String(locale.value).startsWith('zh'))return raw;const days=raw.match(/^(\d+)\s*天$/);if(days)return t('sourcingDetail.businessValues.days',{n:days[1]});const key=businessValueKeys[raw.replace(/\s+/g,'')];return key?t(`sourcingDetail.businessValues.${key}`):raw}
function localizedProductName(line:AnyRow){const source=String(line?.extracted?.product||'—');if(String(locale.value).startsWith('zh'))return source;const product=productDisplays.value[String(line?.productId||'')];if(String(product?.nameEn||'').trim())return product.nameEn;const alias=productAliasKeys[source];return alias?t(`sourcingDetail.productAliases.${alias}`):source}
function demandGroupRowClass({row}: {row: AnyRow}){return row.lines.length>1?'demand-group--multiple':'demand-group--single'}
function demandLineNumbers(group:AnyRow){const values=group.lines.map((line:AnyRow)=>line.lineNo).filter((value:any)=>value!==undefined&&value!==null&&value!=='');return values.length>1?values.join('、'):String(values[0]??'—')}
function demandStandards(group:AnyRow){const values=[...new Set(group.lines.map((line:AnyRow)=>[line.extracted?.materialStandard,line.extracted?.grade].filter(Boolean).join(' / ')).filter(Boolean))];return values.join('、')||'—'}
function localizedLineProduct(lineID:any,fallback='—'){const line=sourceLine(lineID);return line?localizedProductName(line):fallback||'—'}
function localizedCargoSummary(){const lines=rfqEligibleLines.value;if(!lines.length)return shippingCollaboration.value?.shippingRequest?.cargoSummary||'—';return lines.map((line:any)=>`${localizedProductName(line)} ${line.extracted?.quantity||''} ${line.extracted?.quantityUnit||''}`.trim()).join('; ')}
async function loadProductDisplays(){const ids=[...new Set((detail.value?.lines||[]).map((line:any)=>String(line.productId||'')).filter(Boolean))];if(!ids.length){productDisplays.value={};return}const products=await Promise.all(ids.map(productID=>get<any>(`/products/${productID}`,{},quietErrors).then(response=>response.product).catch(()=>undefined)));productDisplays.value=Object.fromEntries(products.filter(Boolean).map((product:any)=>[String(product.id),product]))}
function specificationSummary(extracted:any){const hidden=new Set(['product','quantity','quantity_unit']);const parts=reviewFields.value.filter(field=>!hidden.has(field.key)).map(field=>{const value=readTemplateField(extracted,field.key);return value?`${field.label}: ${localizedBusinessValue(value)}`:''}).filter(Boolean);return parts.join(' · ')||t('sourcingDetail.noExtraSpecs')}
function formatTime(v:string){return v?new Date(v).toLocaleString():'—'}function sourceLineNo(v:string){const lineNo=detail.value?.lines.find((x:any)=>String(x.id)===String(v))?.lineNo;return lineNo||((v===undefined||v===null||v==='')?'—':v)}function isOverdue(x:any){return ['SENT','PARTIALLY_QUOTED'].includes(x.status)&&x.responseDueAt&&new Date(x.responseDueAt).getTime()<Date.now()}function rfqLabel(x:any){return isOverdue(x)?'已逾期':({DRAFT:'草稿',SENT:'已发送',PARTIALLY_QUOTED:'部分报价',QUOTED:'已报价',CLOSED:'已关闭',CANCELLED:'已取消'} as any)[x.status]||x.status}function rfqType(x:any){return isOverdue(x)?'danger':x.status==='QUOTED'?'success':'info'}function openSourceMail(){void router.push({path:'/emails',query:{message:detail.value?.sourceMailId}})}function openSourceFile(){if(detail.value?.sourceFileUrl)window.open(detail.value.sourceFileUrl,'_blank','noopener')}
function openRFQ(){Object.assign(rfq,{supplierId:'',factoryId:'',factoryCode:'',factoryName:'',currency:'USD'});rfqOpen.value=true}function factorySelected(factory:any){rfq.factoryCode=factory?.code||'';rfq.factoryName=factory?.nameZh||factory?.nameEn||''}async function createRFQ(){if(!rfq.supplierId){ElMessage.warning('请选择供应商');return}if(!/^[A-Z]{3}$/.test(String(rfq.currency).trim().toUpperCase())){ElMessage.warning('币种必须是 3 位代码，例如 USD 或 CNY');return}const lineIds=rfqEligibleLines.value.map((line:any)=>Number(line.id));if(!lineIds.length){ElMessage.warning('询盘没有可用于询价的产品明细');return}const sameTarget=rfqs.value.filter(item=>Number(item.supplierId)===Number(rfq.supplierId)&&Number(item.factoryId||0)===Number(rfq.factoryId||0)&&!['CANCELLED','CLOSED'].includes(item.status));if(sameTarget.length){try{await ElMessageBox.confirm(`该供应商${rfq.factoryId?'及工厂':'（未指定工厂）'}已有 ${sameTarget.length} 条有效询价。你仍可建立自己负责的独立询价，系统会分别保留报价人和版本。`,'发现重复供应商',{confirmButtonText:'继续创建我的询价',cancelButtonText:'返回检查',type:'warning'})}catch(action){if(isDialogDismissed(action))return;throw action}}const ownRounds=sameTarget.filter(item=>auth.owns(String(item.createdBy)));const nextRound=ownRounds.reduce((max,item)=>Math.max(max,Number(item.roundNo||1)),0)+1;await post(`/sourcing-cases/${id}/factory-rfqs`,{supplier_id:Number(rfq.supplierId),factory_id:Number(rfq.factoryId||0),factory_code:rfq.factoryCode,factory_name:rfq.factoryName,inquiry_channel:'OTHER',contact_name:'',contact_email:'',contact_value:'',contacted_at:'',inquiry_note:'',round_no:nextRound,currency:String(rfq.currency).trim().toUpperCase(),response_due_at:'',sourcing_line_ids:lineIds});rfqOpen.value=false;await load();ElMessage.success(sameTarget.length?'你的独立工厂询价已创建':'工厂询价已创建')}
async function downloadRFQ(row:any){const f=await download(`/factory-rfqs/${row.id}/workbook`);saveBlob(f.blob,f.fileName||`${row.rfqNo}.xlsx`)}
function handleRFQAction(command:string,row:any){if(command==='download'){void downloadRFQ(row);return}if(command==='quote'){openQuote(row);return}if(command==='import')openImport(row)}

// openQuote 根据 RFQ 包含的产品行创建录入表格，避免员工把报价填到错误产品上。
function openQuote(row:any){quotingRfq.value=row;quoteIncoterm.value='';Object.assign(quoteForm,{currency:row.currency||'USD',quotedAt:'',validUntil:'',delivery:'',paymentTerms:''});const included=new Set((row.sourcingLineIds||[]).map(String));quoteRows.value=(detail.value?.lines||[]).filter((line:any)=>included.has(String(line.id))).map((line:any)=>({sourcingLineId:line.id,product:line.extracted.product,qty:line.extracted.quantity,uom:String(line.extracted.quantityUnit||'').trim().toUpperCase(),unitPrice:'',moq:'',leadTime:''}));quoteOpen.value=true}
async function saveQuote(){const quotedRows=quoteRows.value.filter(row=>String(row.unitPrice).trim()!=='');if(!quotingRfq.value||!quotedRows.length){ElMessage.warning('请至少填写一个产品的报价');return}if(quotedRows.some(row=>Number(row.unitPrice)<0||row.qty===''||Number(row.qty)<=0)){ElMessage.warning('已报价产品必须填写有效单价和大于 0 的可供量');return}saving.value=true;try{await post(`/factory-rfqs/${quotingRfq.value.id}/supplier-quotes`,{quoted_at:quoteForm.quotedAt,valid_until:quoteForm.validUntil,currency:quoteForm.currency,payment_terms:quoteForm.paymentTerms,delivery:quoteForm.delivery,incoterm:quoteIncoterm.value,source:'MANUAL',confirmation_status:'WRITTEN_CONFIRMED',lines:quotedRows.map(row=>({sourcing_line_id:Number(row.sourcingLineId),qty:row.qty,unit_price:row.unitPrice,moq:row.moq,lead_time:row.leadTime}))});quoteOpen.value=false;await load();ElMessage.success('工厂报价新版本已保存，产品报价组已自动更新')}finally{saving.value=false}}
function openQuoteHistory(row:AnyRow){quoteHistoryRows.value=quoteLines.value.filter(item=>String(item.factoryRfqId)===String(row.factoryRfqId)&&String(item.sourcingLineId)===String(row.sourcingLineId)).sort((a,b)=>Number(b.versionNo||0)-Number(a.versionNo||0)||Number(b.quoteId||0)-Number(a.quoteId||0));quoteHistoryTitle.value=`${sourceProduct(row.sourcingLineId)} · ${row.supplierName} · ${row.createdByName||'报价人'}的版本历史`;quoteHistoryOpen.value=true}
function planStatusLabel(value:string){if(isSalesView.value)return ({CONFIRMED:t('sourcingDetail.planStatuses.confirmed'),SUBMITTED_TO_SALES:t('sourcingDetail.planStatuses.submitted'),SUPERSEDED:t('sourcingDetail.planStatuses.historical')} as Record<string,string>)[value]||value;return ({CONFIRMED:'经理已确认',SUBMITTED_TO_SALES:'已提交负责销售',SUPERSEDED:'历史版本'} as Record<string,string>)[value]||value}
function reworkTypeLabel(value:string){return ({REQUOTE:'重新询价/更新报价',RENEGOTIATE:'重新议价',ADD_SUPPLIER:'增加供应商'} as Record<string,string>)[value]||value}
function openProcurementPlan(){procurementPlanForm.managerNote='';planSelectionRows.value=selectablePlanQuoteLines.value.map(row=>({...row,selected:false,selectionType:'RECOMMENDED',priority:1,reason:'',risk:''}));procurementPlanOpen.value=true}
async function createProcurementPlan(){const selected=planSelectionRows.value.filter(row=>row.selected);if(!procurementPlanForm.managerNote.trim()){ElMessage.warning('请填写经理整体意见');return}if(!selected.length){ElMessage.warning('请至少审核一个报价');return}const expired=selected.find(isQuoteExpired);if(expired){ElMessage.warning(`报价“${expired.supplierName||'未命名供应商'} · ${expired.createdByName||expired.buyerName||'未知报价人'} · V${expired.versionNo||expired.quoteVersionNo||1}”已于 ${expired.validUntil} 过期，请刷新后选择有效的新版本`);return}for(const line of rfqEligibleLines.value){if(!selected.some(row=>String(row.sourcingLineId)===String(line.id)&&row.selectionType==='RECOMMENDED')){ElMessage.warning(`产品“${line.extracted.product}”至少需要一个推荐报价`);return}}if(selected.some(row=>!String(row.reason||'').trim())){ElMessage.warning('每个推荐、备选或淘汰判断都需要填写原因');return}const priorityKeys=new Set<string>();for(const row of selected){const key=`${row.sourcingLineId}:${row.selectionType}:${row.priority}`;if(priorityKeys.has(key)){ElMessage.warning('同一产品同类判断的顺序不能重复');return}priorityKeys.add(key)}saving.value=true;try{await post(`/sourcing-cases/${id}/procurement-plans`,{manager_note:procurementPlanForm.managerNote,selections:selected.map(row=>({sourcing_line_id:Number(row.sourcingLineId),supplier_quote_line_id:Number(row.quoteLineId),selection_type:row.selectionType,priority:Number(row.priority),reason:String(row.reason||'').trim(),risk:String(row.risk||'').trim()}))});procurementPlanOpen.value=false;await load();tab.value='plans';ElMessage.success('经理统一采购方案已生成并保留为新版本')}finally{saving.value=false}}
async function submitProcurementPlan(plan:AnyRow){try{await ElMessageBox.confirm(`确认将统一方案 ${plan.planNo} 定向提交给负责销售“${plan.targetSalesName}”？不会发送给其他销售。`,'提交负责销售',{confirmButtonText:'确认提交',cancelButtonText:'取消',type:'warning'})}catch(error){if(isDialogDismissed(error))return;throw error}await post(`/procurement-plans/${plan.id}/submit-to-sales`,{});await load();ElMessage.success(`统一方案已提交给 ${plan.targetSalesName}`)}
function openQuoteRework(row:AnyRow){Object.assign(reworkForm,{planId:procurementPlans.value.find(plan=>plan.status==='CONFIRMED')?.id||0,sourcingLineId:row.sourcingLineId,supplierQuoteLineId:row.quoteLineId,requestType:'RENEGOTIATE',reason:'',supplierName:row.supplierName,productName:sourceProduct(row.sourcingLineId),buyerName:row.createdByName});procurementReworkOpen.value=true}
function openAddSupplierRework(){Object.assign(reworkForm,{planId:procurementPlans.value.find(plan=>plan.status==='CONFIRMED')?.id||0,sourcingLineId:'',supplierQuoteLineId:0,requestType:'ADD_SUPPLIER',reason:'',supplierName:'',productName:'',buyerName:''});procurementReworkOpen.value=true}
async function createProcurementRework(){if(!String(reworkForm.reason||'').trim()){ElMessage.warning('请填写具体原因');return}saving.value=true;try{const endpoint=isSalesView.value?`/sales-inquiries/${id}/procurement-reworks`:`/sourcing-cases/${id}/procurement-reworks`;await post(endpoint,procurementReworkPayload(isSalesView.value,reworkForm));procurementReworkOpen.value=false;await load();tab.value=isSalesView.value?'negotiation':'plans';ElMessage.success('补充询价任务已发布')}finally{saving.value=false}}
function canResolveRework(row:AnyRow){return !isSalesView.value&&canPrice&&row.status==='OPEN'&&(!Number(row.assignedBuyerId||0)||auth.owns(String(row.assignedBuyerId)))}
function reworkStatus(row:AnyRow){if(row.status!=='OPEN')return {label:'已完成',type:'success'};if(canResolveRework(row))return {label:'待我处理',type:'warning'};return {label:`${row.assignedBuyerName||'其他采购'}处理中`,type:'info'}}
function reworkRowClass({row}: {row:AnyRow}){return String(route.query.rework||'')===String(row.id)?'rework-row-highlight':''}
async function resolveRework(row:AnyRow){if(Number(row.finalRecheckTaskId||0)>0){const limit=Number(row.customerIntentQty||0);Object.assign(finalProcurementResolveForm,{id:Number(row.id),note:'',currency:'USD',unitPrice:'',availableQty:limit,customerIntentQty:limit,leadTime:1,deliveryDate:'',paymentTerms:'',incoterm:'',validUntil:''});finalProcurementResolveOpen.value=true;return}const result=await ElMessageBox.prompt('说明重新询价、议价或新增供应商的处理结果。','完成补充任务',{inputPlaceholder:'例如：已上传供应商最新 V2 报价',inputValidator:(value:string)=>!!value.trim()||'请填写处理结果'}).catch(()=>null);if(!result)return;await post(`/procurement-reworks/${row.id}/resolve`,{resolution_note:result.value});await load();ElMessage.success('任务已完成并保留处理记录')}
async function submitFinalProcurementResolve(){const f=finalProcurementResolveForm;if(!f.note||!f.currency||Number(f.unitPrice)<=0||Number(f.availableQty)<=0||Number(f.availableQty)>Number(f.customerIntentQty)||Number(f.leadTime)<=0||!f.deliveryDate||!f.paymentTerms||!f.incoterm||!f.validUntil){ElMessage.warning(Number(f.availableQty)>Number(f.customerIntentQty)?t('sourcingDetail.finalAvailableLimit',{qty:f.customerIntentQty}):'请完整填写最终价格、可供量、交期、条款和有效期');return}saving.value=true;try{await post(`/procurement-reworks/${f.id}/resolve`,{resolution_note:f.note,final_currency:f.currency,final_unit_price:String(f.unitPrice),final_available_qty:String(f.availableQty),final_lead_time:Number(f.leadTime),final_delivery_date:f.deliveryDate,final_payment_terms:f.paymentTerms,final_incoterm:f.incoterm,final_valid_until:f.validUntil});finalProcurementResolveOpen.value=false;await load();ElMessage.success('采购最终复询结果已保存')}finally{saving.value=false}}
function openImport(row:any){importingRfq.value=row;quoteFile.value=null;Object.assign(importForm,{currency:row.currency||'USD',quotedAt:'',validUntil:'',delivery:'',paymentTerms:''});importOpen.value=true}
function selectQuoteFile(event:Event){quoteFile.value=(event.target as HTMLInputElement).files?.[0]??null}
async function fileBase64(file:File){const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return btoa(binary)}
async function importQuote(){if(!importingRfq.value||!quoteFile.value){ElMessage.warning('请选择工厂回传的 XLSX 报价文件');return}if(quoteFile.value.size>2*1024*1024){ElMessage.warning('报价文件不能超过 2 MB');return}saving.value=true;try{await post(`/factory-rfqs/${importingRfq.value.id}/supplier-quotes/import`,{file_data:await fileBase64(quoteFile.value),quoted_at:importForm.quotedAt,valid_until:importForm.validUntil,currency:importForm.currency,payment_terms:importForm.paymentTerms,delivery:importForm.delivery});importOpen.value=false;await load();ElMessage.success('工厂报价已导入')}finally{saving.value=false}}

function quotesForLine(lineID:string){return confirmedComparisonQuoteLines.value.filter(item=>String(item.sourcingLineId)===String(lineID))}function isLowest(row:any){if(isQuoteExpired(row))return false;const group=confirmedComparisonQuoteLines.value.filter(x=>String(x.sourcingLineId)===String(row.sourcingLineId));if(group.length>1&&group.every(x=>x.comparePrice))return Number(row.comparePrice)===Math.min(...group.map(x=>Number(x.comparePrice)));const values=group.filter(x=>x.currency===row.currency).map(x=>Number(x.unitPrice));return values.length>1&&Number(row.unitPrice)===Math.min(...values)}function quoteRowClass({row}:any){return (row.confirmationStatus||'WRITTEN_CONFIRMED')!=='WRITTEN_CONFIRMED'?'quote-pending':''}
function openCostScenario(){Object.assign(costForm,{currency:'USD',allocationBasis:'TONS',marginType:'PERCENT',marginValue:'8'});costSelections.value=rfqEligibleLines.value.map((line:any)=>({sourcingLineId:line.id,lineNo:line.lineNo,product:line.extracted.product,quoteLineId:quotesForLine(line.id)[0]?.quoteLineId||''}));costShippingOptionId.value='';costCharges.splice(0);addCharge();costOpen.value=true}
function shippingStatus(value:string){if(isSalesView.value)return ({WAITING_PARTICIPATION:{label:t('sourcingDetail.shippingStatuses.waiting'),type:'warning'},QUOTING:{label:t('sourcingDetail.shippingStatuses.quoting'),type:'primary'},MANAGER_REVIEW:{label:t('sourcingDetail.shippingStatuses.managerReview'),type:'warning'},PLAN_READY:{label:t('sourcingDetail.shippingStatuses.planReady'),type:'warning'},REQUOTE_REQUIRED:{label:t('sourcingDetail.shippingStatuses.requote'),type:'danger'},PLAN_SUBMITTED_TO_SALES:{label:t('sourcingDetail.shippingStatuses.submitted'),type:'success'}} as any)[value]||{label:t(value?'sourcingDetail.shippingStatuses.processing':'sourcingDetail.shippingStatuses.none'),type:'info'};return ({WAITING_PARTICIPATION:{label:'等待船运人员参与',type:'warning'},QUOTING:{label:'多人船运询价中',type:'primary'},MANAGER_REVIEW:{label:'等待船运经理整合',type:'warning'},PLAN_READY:{label:'经理方案待提交销售',type:'warning'},REQUOTE_REQUIRED:{label:'待重新询价',type:'danger'},PLAN_SUBMITTED_TO_SALES:{label:'经理方案已提交',type:'success'}} as any)[value]||{label:value?'船运处理中':'尚未创建船运任务',type:'info'}}
function shippingBasisLabel(value:string){if(isSalesView.value)return ({PER_TON:t('sourcingDetail.shippingBases.perTon'),PER_CONTAINER:t('sourcingDetail.shippingBases.perContainer'),PER_SHIPMENT:t('sourcingDetail.shippingBases.perShipment'),FIXED:t('sourcingDetail.shippingBases.fixed')} as any)[value]||value;return ({PER_TON:'按吨',PER_CONTAINER:'按柜',PER_SHIPMENT:'按票',FIXED:'固定总额'} as any)[value]||value}
function importShippingCharge(value:any){const plan=submittedShippingPlans.value.find((item:any)=>String(item.id)===String(value));if(!plan)return;for(let i=costCharges.length-1;i>=0;i--){if(costCharges[i].shippingOptionId)costCharges.splice(i,1)};(plan.items||[]).filter((line:any)=>line.selectionType==='RECOMMENDED').forEach((line:any)=>costCharges.push({chargeType:'OCEAN_FREIGHT',customChargeName:'',basis:'FIXED',amount:line.totalFreight,currency:line.currency,source:`${plan.planNo} · ${line.carrierForwarder} · ${line.productName}`,shippingOptionId:plan.id}))}
function chargeTypeLabel(value:string){return chargeTypeLabels[value]||value}
function chargeBasisLabel(value:string){return chargeBasisLabels[value]||value}
function addCharge(){costCharges.push({chargeType:'OTHER',customChargeName:'',basis:'FIXED',amount:'',currency:costForm.currency,source:''})}
async function createCostScenario(){if(costSelections.value.some(line=>!line.quoteLineId)){ElMessage.warning('请为每条产品选择一个工厂报价');return}if(costCharges.some(item=>!String(item.chargeType||'').trim()||item.chargeType==='OTHER'&&!String(item.customChargeName||'').trim()||item.amount===''||Number(item.amount)<0)){ElMessage.warning('请填写具体费用名称和有效金额');return}saving.value=true;try{await post(`/sourcing-cases/${id}/cost-scenarios`,{currency:costForm.currency,allocation_basis:costForm.allocationBasis,margin_type:costForm.marginType,margin_value:costForm.marginValue,selections:costSelections.value.map(line=>({sourcing_line_id:Number(line.sourcingLineId),supplier_quote_line_id:Number(line.quoteLineId)})),charges:costCharges.map(item=>({charge_type:item.chargeType,description:item.chargeType==='OTHER'?String(item.customChargeName).trim():'',basis:item.basis,amount:item.amount,currency:item.currency,source:item.source}))});costOpen.value=false;await load();ElMessage.success('成本方案已创建')}finally{saving.value=false}}
async function openCostDetail(row:any){costDetail.value=(await get<any>(`/cost-scenarios/${row.id}`)).costScenario;costDetailOpen.value=true}
async function confirmCostScenario(row:any){const {value}=await ElMessageBox.prompt('请填写选择该方案的原因，便于后续审批与业务追溯。可说明价格、交期、MOQ、付款条件、质量或供应稳定性等因素。','确认成本方案（中标）',{inputPlaceholder:'请输入选择该方案的主要原因',inputValidator:(v:string)=>!!v.trim()||'请填写选择说明'}).catch(()=>({value:''}));if(!value)return;await post(`/cost-scenarios/${row.id}/confirm`,{reason:value});await load();ElMessage.success('成本方案已确认，选择说明已写入变更记录')}
async function joinCase(){await post(`/sourcing-cases/${id}/participants`,{});await load();ElMessage.success('已加入询价，可与其他采购共同处理')}
async function requestPrimary(){const hadPrimary=!!primaryParticipant.value;await post(`/sourcing-cases/${id}/primary-request`,{});await load();ElMessage.success(hadPrimary?'主责申请已提交采购经理':'你已成为本案件主责采购')}
async function assignPrimary(item:AnyRow){let reason='';if(primaryParticipant.value){const result=await ElMessageBox.prompt(`将主责采购由 ${primaryParticipant.value.employeeName} 更换为 ${item.employeeName}，请填写原因。`,'更换主责采购',{inputPlaceholder:'例如：供应商分工调整或原主责请假',inputValidator:(value:string)=>!!value.trim()||'更换主责必须填写原因'}).catch(()=>null);if(!result)return;reason=result.value}await post(`/sourcing-cases/${id}/primary-buyer`,{employee_id:Number(item.employeeId),reason});await load();ElMessage.success(`${item.employeeName} 已设为主责采购`)}
async function returnCase(){if(!returnForm.fields.length||!returnForm.reason.trim()){ElMessage.warning('请选择缺失资料并填写简短原因');return}await post(`/sourcing-cases/${id}/return`,{missing_fields:returnForm.fields,reason:returnForm.reason});returnOpen.value=false;await load();ElMessage.success('已退回销售补充资料')}
async function submitCostToSales(row:any){try{await ElMessageBox.confirm(`确认将需求 V${row.requirementVersionNo||1} 对应的成本 C${row.versionNo||1} 提交销售？提交后销售可据此生成客户报价。`,'提交成本给销售',{confirmButtonText:'确认提交',cancelButtonText:'取消',type:'warning'})}catch(error){if(isDialogDismissed(error))return;throw error}await post(`/cost-scenarios/${row.id}/submit-to-sales`,{});await load();ElMessage.success('成本方案已提交销售')}
async function createCustomerQuotation(row:any){if(Number(row.customerQuotationId||0)>0){await router.push(`/sales/inquiries/${id}`);tab.value='customerQuote';return}if(!Number(detail.value?.customerId||0)){customers.value=(await get<any>('/customers',{page_size:200,status:'ACTIVE'})).customers||[];pendingCostScenario.value=row;mappedCustomerId.value='';customerMapOpen.value=true;return}await performCreateCustomerQuotation(row,detail.value?.customerId)}
async function submitMappedCustomer(){if(!pendingCostScenario.value||!mappedCustomerId.value){ElMessage.warning('请选择内部客户');return}customerMapOpen.value=false;await performCreateCustomerQuotation(pendingCostScenario.value,mappedCustomerId.value)}
async function performCreateCustomerQuotation(row:any,customerID:string){try{await ElMessageBox.confirm(`确认根据成本方案 V${row.versionNo||1}（${row.scenarioNo||'已确认方案'}）生成客户报价单？生成后将进入销售模块继续编辑报价内容。`,'生成客户报价单',{confirmButtonText:'确认生成',cancelButtonText:'取消',type:'warning'})}catch(error){if(isDialogDismissed(error))return;throw error}saving.value=true;try{const response=await post<any>(`/cost-scenarios/${row.id}/create-customer-quotation`,{customer_id:Number(customerID)});ElMessage.success(`报价单 ${response.quoteNo} 已生成`);await load();await router.push(`/sales/inquiries/${id}`);tab.value='customerQuote'}finally{saving.value=false}}

function salesPlanStatusLabel(value:string){return ({PRESENTED:t('sourcingDetail.salesPlanStatuses.presented'),SUPERSEDED:t('sourcingDetail.salesPlanStatuses.historical'),REWORK_REQUESTED:t('sourcingDetail.salesPlanStatuses.rework')} as Record<string,string>)[value]||value}
function salesPlanKey(plan:AnyRow){return String(plan.id)}
function currentSalesPlan(){return salesPlans.value.find(plan=>plan.status==='PRESENTED')||salesPlans.value[0]}
function syncSalesPlanExpansion(){const current=currentSalesPlan(),currentId=current?salesPlanKey(current):'';if(currentId===expandedCurrentSalesPlanId)return;expandedCurrentSalesPlanId=currentId;expandedSalesPlanIds.value=new Set(currentId?[currentId]:[])}
function isSalesPlanExpanded(plan:AnyRow){return expandedSalesPlanIds.value.has(salesPlanKey(plan))}
function toggleSalesPlan(plan:AnyRow){const next=new Set(expandedSalesPlanIds.value),key=salesPlanKey(plan);next.has(key)?next.delete(key):next.add(key);expandedSalesPlanIds.value=next}
function expandAllSalesPlans(){expandedSalesPlanIds.value=new Set(salesPlans.value.map(salesPlanKey))}
function collapseHistoricalSalesPlans(){const current=currentSalesPlan();expandedSalesPlanIds.value=new Set(current?[salesPlanKey(current)]:[])}
function customerSelectionKey(selection:AnyRow){return String(selection.id)}
function currentCustomerSelection(){return customerSelections.value.find(selection=>!['INVALIDATED','CUSTOMER_REJECTED'].includes(selection.status))||customerSelections.value[0]}
function syncCustomerSelectionExpansion(){const current=currentCustomerSelection(),currentId=current?customerSelectionKey(current):'';if(currentId===expandedCurrentCustomerSelectionId)return;expandedCurrentCustomerSelectionId=currentId;expandedCustomerSelectionIds.value=new Set(currentId?[currentId]:[])}
function isCustomerSelectionExpanded(selection:AnyRow){return expandedCustomerSelectionIds.value.has(customerSelectionKey(selection))}
function toggleCustomerSelection(selection:AnyRow){const next=new Set(expandedCustomerSelectionIds.value),key=customerSelectionKey(selection);next.has(key)?next.delete(key):next.add(key);expandedCustomerSelectionIds.value=next}
function expandAllCustomerSelections(){expandedCustomerSelectionIds.value=new Set(customerSelections.value.map(customerSelectionKey))}
function collapseHistoricalCustomerSelections(){const current=currentCustomerSelection();expandedCustomerSelectionIds.value=new Set(current?[customerSelectionKey(current)]:[])}
function customerSelectionStatus(value:string){return ({INTENT_RECHECK_PENDING:{label:t('sourcingDetail.customerSelectionStatuses.pending'),type:'warning'},AWAITING_CUSTOMER_CONFIRMATION:{label:t('sourcingDetail.customerSelectionStatuses.awaitingCustomer'),type:'warning'},CUSTOMER_CONFIRMED:{label:t('sourcingDetail.customerSelectionStatuses.confirmed'),type:'success'},CUSTOMER_REJECTED:{label:t('sourcingDetail.customerSelectionStatuses.rejected'),type:'danger'},FINAL_RECHECK_PENDING:{label:t('sourcingDetail.customerSelectionStatuses.pending'),type:'warning'},FINAL_RECHECKED:{label:t('sourcingDetail.customerSelectionStatuses.awaitingCustomer'),type:'warning'},INVALIDATED:{label:t('sourcingDetail.customerSelectionStatuses.invalidated'),type:'info'}} as Record<string,any>)[value]||{label:value,type:'info'}}
function resolvedRecheckCount(selection:AnyRow){return (selection.recheckTasks||[]).filter((task:AnyRow)=>task.status==='RESOLVED').length}
function feedbackResultLabel(value:string){return ({CONTINUE_NEGOTIATION:t('sourcingDetail.feedbackDialog.continue'),REQUOTE_REQUIRED:t('sourcingDetail.feedbackDialog.requote'),COMMENT:t('sourcingDetail.feedbackDialog.comment')} as Record<string,string>)[value]||value}
function feedbackChannelLabel(value:string){return ({PHONE:t('sourcingDetail.feedbackDialog.phone'),EMAIL:t('sourcingDetail.feedbackDialog.email'),MEETING:t('sourcingDetail.feedbackDialog.meeting'),OTHER:t('sourcingDetail.feedbackDialog.other')} as Record<string,string>)[value]||value}
function selectedProcurementPlan(){return submittedProcurementPlans.value.find(plan=>String(plan.id)===String(salesPlanForm.procurementPlanId))}
function selectedShippingPlan(){return submittedShippingPlans.value.find((plan:any)=>String(plan.id)===String(salesPlanForm.shippingPlanId))}
function shippingItemsForLine(lineID:any){return (selectedShippingPlan()?.items||[]).filter((item:any)=>String(item.sourcingLineId)===String(lineID))}
function confirmedCostLine(lineID:any){return (salesCostBasis.value?.lines||[]).find((line:any)=>String(line.sourcingLineId)===String(lineID))}
function applySuggestedPrice(row:AnyRow){const costLine=confirmedCostLine(row.sourcingLineId),suggestion=suggestCustomerUnitPrice({purchaseCurrency:row.currency||'USD',purchaseUnitPrice:row.unitPrice,quantity:row.availableQty||sourceQuantity(row.sourcingLineId),costCurrency:salesCostBasis.value?.currency,confirmedCustomerUnitPrice:costLine?.customerUnitPrice});row.customerCurrency=suggestion.currency;row.customerUnitPrice=suggestion.value;const key=suggestion.source==='CONFIRMED_COST'?'confirmedCost':'purchaseOnly';row.priceSource=t(`sourcingDetail.priceSources.${key}`,{purchase:String(row.currency||'USD').toUpperCase(),shipping:String(row.currency||'USD').toUpperCase()})}
function salesPlanSelectionChanged(row:AnyRow){if(row.selected&&!String(row.customerUnitPrice||'').trim())applySuggestedPrice(row)}
function salesPlanRowClass({row}:{row:AnyRow}){return row.selected?'':'sales-plan-row--excluded'}
function resetSalesPlanRows(){const plan=selectedProcurementPlan();salesPlanRows.value=(plan?.items||[]).filter((item:any)=>item.selectionType!=='REJECTED').map((item:any)=>({
  ...item,selected:item.selectionType==='RECOMMENDED',procurementPlanItemId:item.id,
  shippingPlanItemId:'',
  optionType:item.selectionType==='RECOMMENDED'?'PRIMARY':'ALTERNATIVE',priority:Number(item.priority||1),
  customerCurrency:item.currency||'USD',customerUnitPrice:'',priceSource:'',promisedDeliveryDate:'',lineNote:'',
}));salesPlanRows.value.filter(row=>row.selected).forEach(applySuggestedPrice);const groups=new Map<string,AnyRow>();for(const item of (selectedShippingPlan()?.items||[]).filter((row:any)=>row.selectionType!=='REJECTED')){const key=String(item.shippingOptionId||[item.carrierForwarder,item.serviceOptionName,item.portOfLoading,item.portOfDischarge,item.estimatedDeparture,item.estimatedArrival,item.currency,item.totalFreight].join('|'));if(!groups.has(key))groups.set(key,{...item,selected:true,shippingPlanItemIds:[],productNames:[],customerCurrency:item.currency||'USD',customerFreightAmount:item.totalFreight||'0'});const group=groups.get(key)!;group.shippingPlanItemIds.push(Number(item.id));if(!group.productNames.includes(item.productName))group.productNames.push(item.productName)}salesShippingRows.value=[...groups.values()]}
function openSalesPlan(){const procurement=submittedProcurementPlans.value[0];Object.assign(salesPlanForm,{procurementPlanId:procurement?.id||'',shippingPlanId:submittedShippingPlans.value[0]?.id||'',validUntil:'',customerNote:'',internalNote:''});salesCostBasis.value=[...confirmedCosts.value].sort((a,b)=>Number(b.versionNo||0)-Number(a.versionNo||0))[0];resetSalesPlanRows();salesPlanOpen.value=true}
async function createSalesPlan(){const selected=salesPlanRows.value.filter(row=>row.selected),shipping=salesShippingRows.value.filter(row=>row.selected);if(!salesPlanForm.validUntil){ElMessage.warning(t('sourcingDetail.salesPlanDialog.validRequired'));return}if(!selected.length){ElMessage.warning(t('sourcingDetail.salesPlanDialog.productRequired'));return}for(const line of rfqEligibleLines.value){if(!selected.some(row=>String(row.sourcingLineId)===String(line.id)&&row.optionType==='PRIMARY')){ElMessage.warning(t('sourcingDetail.salesPlanDialog.primaryRequired',{product:line.extracted.product}));return}}if(selected.some(row=>!String(row.customerUnitPrice||'').trim()||Number(row.customerUnitPrice)<0)||shipping.some(row=>!String(row.customerFreightAmount||'').trim()||Number(row.customerFreightAmount)<0)){ElMessage.warning(t('sourcingDetail.salesPlanDialog.customerPriceRequired'));return}saving.value=true;try{await post(`/sales-inquiries/${id}/sales-plans`,{procurement_plan_id:Number(salesPlanForm.procurementPlanId),shipping_plan_id:Number(salesPlanForm.shippingPlanId||0),valid_until:salesPlanForm.validUntil,customer_note:salesPlanForm.customerNote,internal_note:salesPlanForm.internalNote,items:selected.map(row=>({sourcing_line_id:Number(row.sourcingLineId),procurement_plan_item_id:Number(row.procurementPlanItemId),shipping_plan_item_id:0,option_type:row.optionType,priority:Number(row.priority),customer_currency:String(row.customerCurrency||'USD').toUpperCase(),customer_unit_price:String(row.customerUnitPrice),promised_delivery_date:row.promisedDeliveryDate||'',line_note:row.lineNote||''})),shipping_options:shipping.map(row=>({shipping_plan_item_ids:row.shippingPlanItemIds,customer_currency:String(row.customerCurrency||'USD').toUpperCase(),customer_freight_amount:String(row.customerFreightAmount),customer_note:''}))});salesPlanOpen.value=false;await load();tab.value='negotiation';ElMessage.success(t('sourcingDetail.salesPlanDialog.saved'))}finally{saving.value=false}}
function contactLabel(contact:AnyRow){return [contact.name,contact.title,contact.email].filter(Boolean).join(' · ')}
async function loadCustomerContacts(){customerContacts.value=[];const customerId=Number(detail.value?.customerId||0);if(!customerId)return;try{const response=await get<any>(`/sourcing-customer-options/${customerId}/contacts`,{},quietErrors);customerContacts.value=response.contacts||[]}catch{customerContacts.value=[]}}
async function openFeedback(){const plan=salesPlans.value.find(item=>item.status==='PRESENTED')||salesPlans.value[0];await loadCustomerContacts();const preferred=detail.value?.contactName||customerContacts.value.find(item=>item.isPrimary)?.name||customerContacts.value[0]?.name||'';Object.assign(feedbackForm,{salesPlanId:plan?.id||'',contactName:preferred,channel:'PHONE',result:'CONTINUE_NEGOTIATION',summary:'',contactedAt:new Date().toISOString()});feedbackOpen.value=true}
async function addCustomerFeedback(){if(!feedbackForm.salesPlanId||!feedbackForm.contactedAt||!String(feedbackForm.summary).trim()){ElMessage.warning('请选择沟通方案并填写时间和反馈摘要');return}saving.value=true;try{await post(`/sales-inquiries/${id}/customer-feedback`,{sales_plan_id:Number(feedbackForm.salesPlanId),contact_name:feedbackForm.contactName,channel:feedbackForm.channel,result:feedbackForm.result,summary:String(feedbackForm.summary).trim(),contacted_at:feedbackForm.contactedAt});feedbackOpen.value=false;await load();tab.value='negotiation';ElMessage.success('客户反馈已登记')}finally{saving.value=false}}
const customerSelectionPlan=computed(()=>salesPlans.value.find(plan=>String(plan.id)===String(customerSelectionForm.salesPlanId)))
const customerSelectionGroups=computed(()=>{const groups=new Map<string,AnyRow>();for(const item of customerSelectionPlan.value?.items||[]){const key=String(item.sourcingLineId);if(!groups.has(key))groups.set(key,{sourcingLineId:item.sourcingLineId,productName:item.productName,items:[]});groups.get(key)!.items.push(item)}return [...groups.values()]})
function selectedCustomerItemForGroup(group:AnyRow){const id=Number(customerSelectionForm.selectedByLine?.[String(group.sourcingLineId)]||0);return (group.items||[]).find((item:AnyRow)=>Number(item.id)===id)}
function customerProductSelectionChanged(group:AnyRow,value:any){const key=String(group.sourcingLineId),item=(group.items||[]).find((row:AnyRow)=>Number(row.id)===Number(value));if(!item){delete customerSelectionForm.confirmedQtyByLine[key];return}customerSelectionForm.confirmedQtyByLine[key]=defaultIntentQuantity(sourceQuantity(group.sourcingLineId),item.quotedQty)}
function selectedCustomerItems(){const ids=new Set(Object.values(customerSelectionForm.selectedByLine||{}).map(Number).filter(Boolean));return (customerSelectionPlan.value?.items||[]).filter((item:AnyRow)=>ids.has(Number(item.id))).map((item:AnyRow)=>({...item,confirmedQty:Number(customerSelectionForm.confirmedQtyByLine?.[String(item.sourcingLineId)]||0)}))}
function lineSubtotal(item:AnyRow){const qty=Number(customerSelectionForm.confirmedQtyByLine?.[String(item.sourcingLineId)]||item.confirmedQty||item.quotedQty||0);return intentLineSubtotal(item.customerUnitPrice,qty)}
function shippingCompatible(group:AnyRow,option:AnyRow){const lines=new Map((option.lines||[]).map((line:AnyRow)=>[Number(line.sourcingLineId),line]));return group.items.every((item:AnyRow)=>{const line:any=lines.get(Number(item.sourcingLineId));if(!line||Number(line.quotedQty||0)<Number(item.confirmedQty||0))return false;const demandPort=String(sourceLine(item.sourcingLineId)?.extracted?.port||'').trim().toLowerCase(),discharge=String(option.portOfDischarge||'').trim().toLowerCase();if(demandPort&&discharge&&demandPort!==discharge)return false;if(item.promisedDeliveryDate&&option.estimatedArrival&&String(option.estimatedArrival)>String(item.promisedDeliveryDate))return false;return !(option.validUntil&&String(option.validUntil)<new Date().toISOString().slice(0,10))})}
const customerShipmentBatches=computed(()=>{const groups=new Map<string,AnyRow>();for(const item of selectedCustomerItems()){const key=`SUPPLIER:${Number(item.supplierId||0)}:FACTORY:${Number(item.factoryId||0)}`;if(!groups.has(key))groups.set(key,{key,supplierName:item.supplierName,factoryName:item.factoryName,lineIds:new Set<number>(),productNames:[],items:[]});const group=groups.get(key)!;group.lineIds.add(Number(item.sourcingLineId));group.items.push(item);if(!group.productNames.includes(item.productName))group.productNames.push(item.productName)}for(const group of groups.values())group.compatibleOptions=(customerSelectionPlan.value?.shippingOptions||[]).filter((option:AnyRow)=>shippingCompatible(group,option));return [...groups.values()]})
const customerSelectionTotals=computed(()=>{const totals=new Map<string,number>();for(const item of selectedCustomerItems()){const currency=String(item.customerCurrency||'USD'),value=Number(item.customerUnitPrice||0)*Number(item.confirmedQty||0);totals.set(currency,(totals.get(currency)||0)+value)}for(const batch of customerShipmentBatches.value){const option=(batch.compatibleOptions||[]).find((row:AnyRow)=>Number(row.id)===Number(customerSelectionForm.selectedShippingByGroup?.[batch.key]));if(option){const currency=String(option.customerCurrency||'USD');totals.set(currency,(totals.get(currency)||0)+Number(option.customerFreightAmount||0))}}return [...totals.entries()].map(([currency,amount])=>({currency,amount:amount.toFixed(2)}))})
async function openCustomerSelection(plan:AnyRow){await loadCustomerContacts();const selectedByLine:Record<string,number>={};for(const item of plan.items||[])selectedByLine[String(item.sourcingLineId)]=0;Object.assign(customerSelectionForm,{salesPlanId:Number(plan.id),customerContact:detail.value?.contactName||customerContacts.value.find(item=>item.isPrimary)?.name||customerContacts.value[0]?.name||'',confirmationNote:'',customerConfirmedAt:new Date().toISOString(),selectedByLine,confirmedQtyByLine:{},selectedShippingByGroup:{}});customerSelectionOpen.value=true}
async function confirmCustomerSelection(){const items=selectedCustomerItems();if(!items.length){ElMessage.warning(t('sourcingDetail.customerSelectionDialog.selectRequired'));return}if(items.some((item:AnyRow)=>validateIntentQuantity(item.confirmedQty,item.quotedQty)==='required')){ElMessage.warning(t('sourcingDetail.customerSelectionDialog.quantityRequired'));return}if(items.some((item:AnyRow)=>validateIntentQuantity(item.confirmedQty,item.quotedQty)==='exceeds_available')){ElMessage.warning(t('sourcingDetail.customerSelectionDialog.quantityExceedsAvailable'));return}if(!customerSelectionForm.customerConfirmedAt){ElMessage.warning(t('sourcingDetail.customerSelectionDialog.timeRequired'));return}if(customerShipmentBatches.value.some((batch:AnyRow)=>Number(customerSelectionForm.selectedShippingByGroup?.[batch.key]||0)===0)){ElMessage.warning(t('sourcingDetail.customerSelectionDialog.shippingRequired'));return}const shipmentChoices=customerShipmentBatches.value.map((batch:AnyRow)=>{const choice=Number(customerSelectionForm.selectedShippingByGroup?.[batch.key]||0);return{shipment_group_key:batch.key,sales_shipping_option_id:choice>0?choice:0,customer_managed:choice===-1}});saving.value=true;try{await post(`/sales-inquiries/${id}/customer-selections`,{sales_plan_id:Number(customerSelectionForm.salesPlanId),sales_plan_item_ids:items.map((item:AnyRow)=>Number(item.id)),confirmed_quantities:items.map((item:AnyRow)=>String(item.confirmedQty)),shipment_choices:shipmentChoices,customer_contact:customerSelectionForm.customerContact,confirmation_note:customerSelectionForm.confirmationNote,customer_confirmed_at:customerSelectionForm.customerConfirmedAt});customerSelectionOpen.value=false;await load();tab.value='negotiation';ElMessage.success(t('sourcingDetail.customerSelectionDialog.saved'))}finally{saving.value=false}}
async function createFormalQuotation(selection:AnyRow){saving.value=true;try{const response=await post<any>(`/sales-inquiries/${id}/customer-selections/${selection.id}/formal-quotation`,{});ElMessage.success(t('sourcingDetail.formalQuotationCreated',{no:response.quotation?.quoteNo||''}));tab.value='customerQuote';quotationRefreshToken.value+=1}finally{saving.value=false}}
async function openCustomerDecision(selection:AnyRow,accepted:boolean){await loadCustomerContacts();Object.assign(customerDecisionForm,{selectionId:Number(selection.id),accepted,customerContact:selection.customerContact||detail.value?.contactName||customerContacts.value.find(item=>item.isPrimary)?.name||customerContacts.value[0]?.name||'',decisionNote:'',decidedAt:new Date().toISOString(),itemPrices:(selection.items||[]).map((item:AnyRow)=>{const task=(selection.recheckTasks||[]).find((entry:AnyRow)=>entry.taskDomain==='PROCUREMENT'&&Number(entry.selectionItemId)===Number(item.id));return{selectionItemId:Number(item.id),productName:item.productName,supplierName:item.supplierName,currency:item.customerCurrency||'USD',unitPrice:item.customerUnitPrice||'',uomCode:item.uomCode,paymentTerms:task?.finalPaymentTerms||'',incoterm:task?.finalIncoterm||'',requiredDate:task?.finalDeliveryDate||item.promisedDeliveryDate||''}}),shipmentPrices:(selection.shipments||[]).map((shipment:AnyRow)=>({selectionShipmentId:Number(shipment.id),carrierForwarder:shipment.carrierForwarder,currency:shipment.customerCurrency||'USD',freightAmount:shipment.customerFreightAmount||''}))});customerDecisionOpen.value=true}
async function submitCustomerDecision(){const f=customerDecisionForm;if(!f.decidedAt||!String(f.decisionNote).trim()){ElMessage.warning(t('sourcingDetail.customerDecisionRequired'));return}if(f.accepted&&(f.itemPrices.some((row:AnyRow)=>Number(row.unitPrice)<=0)||f.shipmentPrices.some((row:AnyRow)=>Number(row.freightAmount)<=0))){ElMessage.warning(t('sourcingDetail.finalCustomerPriceRequired'));return}if(f.accepted&&f.itemPrices.some((row:AnyRow)=>!String(row.paymentTerms||'').trim()||!String(row.incoterm||'').trim()||!row.requiredDate)){ElMessage.warning(t('sourcingDetail.finalCustomerTermsRequired'));return}saving.value=true;try{await post(`/sales-inquiries/${id}/customer-selections/decision`,customerDecisionPayload(f));customerDecisionOpen.value=false;await load();ElMessage.success(t('sourcingDetail.customerDecisionSaved'))}finally{saving.value=false}}
function procurementSourceItem(plan:AnyRow,row:AnyRow){const sourcePlan=procurementPlans.value.find(item=>String(item.id)===String(plan.procurementPlanId));return sourcePlan?.items?.find((item:any)=>String(item.id)===String(row.procurementPlanItemId))}
function shippingSourceItem(row:AnyRow){for(const plan of submittedShippingPlans.value){const item=(plan.items||[]).find((entry:any)=>String(entry.id)===String(row.shippingPlanItemId));if(item)return item}return undefined}
function openSalesProcurementRework(plan?:AnyRow,row?:AnyRow){const source=plan&&row?procurementSourceItem(plan,row):undefined;Object.assign(reworkForm,{planId:plan?.id||salesPlans.value.find(item=>item.status==='PRESENTED')?.id||salesPlans.value[0]?.id||0,sourcingLineId:row?.sourcingLineId||'',supplierQuoteLineId:source?.supplierQuoteLineId||0,requestType:source?'RENEGOTIATE':'ADD_SUPPLIER',reason:'',supplierName:source?.supplierName||'',productName:row?.productName||'',buyerName:source?.buyerName||''});procurementReworkOpen.value=true}
function openSalesShippingRework(plan?:AnyRow,row?:AnyRow){const source=row?shippingSourceItem(row):undefined;Object.assign(shippingReworkForm,{salesPlanId:plan?.id||salesPlans.value.find(item=>item.status==='PRESENTED')?.id||salesPlans.value[0]?.id||0,sourcingLineId:row?.sourcingLineId||'',shippingOptionLineId:source?.shippingOptionLineId||0,requestType:source?'RENEGOTIATE':'ADD_CARRIER',reason:''});shippingReworkOpen.value=true}
function openSalesShippingReworkOption(plan:AnyRow,option:AnyRow){const line=option.lines?.[0];Object.assign(shippingReworkForm,{salesPlanId:Number(plan.id),sourcingLineId:Number(line?.sourcingLineId||0),shippingOptionLineId:Number(line?.shippingOptionLineId||0),requestType:'RENEGOTIATE',reason:''});shippingReworkOpen.value=true}
async function createShippingRework(){if(!String(shippingReworkForm.reason).trim()){ElMessage.warning('请填写具体原因');return}saving.value=true;try{const shippingOptionLineId=Number(shippingReworkForm.shippingOptionLineId||0);await post(`/sales-inquiries/${id}/shipping-reworks`,{sales_plan_id:Number(shippingReworkForm.salesPlanId||0),sourcing_line_id:Number(shippingReworkForm.sourcingLineId||0),shipping_option_line_id:shippingOptionLineId,request_type:shippingOptionLineId>0?(shippingReworkForm.requestType==='REQUOTE'?'REQUOTE':'RENEGOTIATE'):'ADD_CARRIER',reason:String(shippingReworkForm.reason).trim()});shippingReworkOpen.value=false;await load();tab.value='negotiation';ElMessage.success('船运补充任务已发布')}finally{saving.value=false}}
const stopLive=onLive(event=>{if(event.type==='requirement.changed'&&!loading.value)void load()})
onMounted(load)
onUnmounted(stopLive)
